INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('579f2f8d-aaaa-4fc4-a794-ea2075376210', '1a5a2e56-1516-43fd-87dc-8fe04536fb32', 0, 'Bypass (altering the route of passage of the contents of a tubular body part, here creating a new connection for blood flow)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d110e9c0-60c7-4d08-95d0-b9a477fa53ec', '1a5a2e56-1516-43fd-87dc-8fe04536fb32', 1, 'Restriction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3a5c4a15-5ba9-4f73-8bf9-0664b6c150de', '1a5a2e56-1516-43fd-87dc-8fe04536fb32', 2, 'Occlusion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fef033b-24d3-41b4-a482-4b429d2962a4', '1a5a2e56-1516-43fd-87dc-8fe04536fb32', 3, 'Dilation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('114fea20-bc45-4b63-acb7-5a3f843a6190', 'f16611d4-7c6a-4299-af87-709901571ab3', 0, 'Each hemodialysis session/procedure performed during the stay is coded per the applicable ICD-10-PCS extracorporeal/performance code(s), in addition to appropriately coding the reason for the inpatient admission and the ESRD diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67108d56-fde4-48b4-8a5d-12a18a8c81b4', 'f16611d4-7c6a-4299-af87-709901571ab3', 1, 'Dialysis is never separately coded during an unrelated inpatient stay');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70b0c9fa-dee1-48cb-bb4a-481feecc51f0', 'f16611d4-7c6a-4299-af87-709901571ab3', 2, 'Only the ESRD diagnosis is coded; the actual dialysis procedure sessions are never coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a561ddf-7729-4a36-9f52-43c57c174471', 'f16611d4-7c6a-4299-af87-709901571ab3', 3, 'Dialysis procedures are coded identically to a diagnostic blood draw');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7284bfb8-6b28-4a53-8372-9cd84a7ca34d', '7cdf3052-9a48-43f7-a074-409d2dca3a62', 0, 'Insertion (putting in a nonbiological device that monitors, assists, performs, or prevents a physiological function without physically taking the place of a body part)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0405b9d8-3d6a-4da3-9775-3e7d4c27ab49', '7cdf3052-9a48-43f7-a074-409d2dca3a62', 1, 'Replacement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f827759a-fccb-4407-ad5e-9d7068af641d', '7cdf3052-9a48-43f7-a074-409d2dca3a62', 2, 'Bypass');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ae58b33-2580-45e0-9e21-0d8f9bc4bd38', '7cdf3052-9a48-43f7-a074-409d2dca3a62', 3, 'Restriction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a0da4eb-13a9-4ded-9a21-41f354221bc5', 'b4de3e14-e310-405b-9a73-c01080171945', 0, 'A combination code capturing type 2 diabetes with chronic kidney disease, per the presumed-causal-relationship principle already discussed for diabetes and CKD, with the specific CKD stage also coded when documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3850667f-ef54-405b-ad7a-b801af96666e', 'b4de3e14-e310-405b-9a73-c01080171945', 1, 'CKD and diabetes are always coded as entirely separate, unrelated conditions with no combination logic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b005f5e-433e-4964-a2a8-0d5672fb8d01', 'b4de3e14-e310-405b-9a73-c01080171945', 2, 'Only the CKD stage is coded; diabetes is disregarded once CKD develops');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9137435d-1a81-406a-97e8-2b1ea5076ee9', 'b4de3e14-e310-405b-9a73-c01080171945', 3, 'Diabetic nephropathy and diabetic CKD are two different conditions requiring entirely different diabetes code categories with no overlap');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aefd0bbe-fd7b-4160-b08e-c46e7fa820ff', '252fb9c1-5fb8-4b60-a585-56b7b6b3925f', 0, 'Drainage (taking or letting out fluids from a body part), likely with a diagnostic qualifier since the purpose is diagnostic sampling rather than therapeutic fluid removal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab513588-350b-473f-958c-465ad3e94825', '252fb9c1-5fb8-4b60-a585-56b7b6b3925f', 1, 'Extraction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b33cfc0c-49ff-4618-8c80-47500536b303', '252fb9c1-5fb8-4b60-a585-56b7b6b3925f', 2, 'Excision');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('159ed09e-c7a7-4a9a-889b-85e1121f34dd', '252fb9c1-5fb8-4b60-a585-56b7b6b3925f', 3, 'Fragmentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ac35e23-69bc-4049-b096-9714a2099967', 'cbbe48a4-be09-435e-806a-7641c3484eaf', 0, 'Extraction (pulling or stripping out, by the use of force, a foreign body or the patient''s own material lodged in a body part) or Extirpation depending on the specific nature of what is being removed, consistent with the same Extraction-versus-Extirpation distinction already covered for other solid-matter-removal scenarios');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01a24a45-ebf3-4f40-a96c-11a3a1c272a2', 'cbbe48a4-be09-435e-806a-7641c3484eaf', 1, 'Insertion, since the bronchoscope is inserted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b22ed4bd-513d-4b16-bbce-92248a170224', 'cbbe48a4-be09-435e-806a-7641c3484eaf', 2, 'Replacement, since airway patency is restored');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a131d116-a1e8-4522-814d-d81a8d022e36', 'cbbe48a4-be09-435e-806a-7641c3484eaf', 3, 'Supplement, since the airway is reinforced');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8cf3f23f-e74f-463b-92c2-a1bedbe221f9', 'e560f0f6-2366-4069-9df7-fbf696327dfa', 0, 'The biopsy is generally coded using the Excision root operation with the diagnostic qualifier, reflecting that a portion of the body part (not all of it) was removed for diagnostic purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8336a3f-3158-4a06-b14c-7c8af9d4d56f', 'e560f0f6-2366-4069-9df7-fbf696327dfa', 1, 'The biopsy is coded using Resection, since the entire ulcer was removed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0c4ee19-f52d-4cfc-8ad7-6fce9c2fa85d', 'e560f0f6-2366-4069-9df7-fbf696327dfa', 2, 'Biopsies are never separately coded from the diagnostic endoscopy procedure itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d25956a3-2a7d-4006-a725-09140cfd3684', 'e560f0f6-2366-4069-9df7-fbf696327dfa', 3, 'The biopsy is coded using Extraction regardless of the specific technique used');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c5dce83-10e8-4ecc-9e0d-9ad3bbdf2a09', '23cad882-023e-4b1c-9802-77374989a2dd', 0, 'The polypectomy is generally coded using the Excision root operation (removing a portion of the colon''s mucosal tissue where the polyp is located), not Resection, since only a portion (not the entire colon) is removed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8cf4a10-e55d-433d-b272-57209df56500', '23cad882-023e-4b1c-9802-77374989a2dd', 1, 'The polypectomy is coded using Resection, since the entire polyp was removed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ab0d3f4-47dd-40c0-9ebe-90e132d18bb1', '23cad882-023e-4b1c-9802-77374989a2dd', 2, 'Polypectomy is never separately coded from the diagnostic colonoscopy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4994d890-4725-4d4a-99e1-e9ffc5dda137', '23cad882-023e-4b1c-9802-77374989a2dd', 3, 'Polypectomy is coded using the Destruction root operation exclusively, regardless of technique');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('585c1486-386b-44e2-b4e7-d24e3b7b323c', 'b6138108-9fb3-4030-a5df-7900f78d098a', 0, 'This scenario would most likely map to the Destruction root operation, since tissue is eradicated via energy application with none of it physically taken out — distinct from Excision, which requires that tissue actually be removed from the body');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6eed0a9-ab08-44f1-881b-9adf1b77effc', 'b6138108-9fb3-4030-a5df-7900f78d098a', 1, 'This is always coded identically to a snare polypectomy (Excision) regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b8e671a1-6bc1-43e7-8279-39005b96bf95', 'b6138108-9fb3-4030-a5df-7900f78d098a', 2, 'This procedure can never be coded in ICD-10-PCS');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1c15534c-78af-4f9e-9c19-7c9430081827', 'b6138108-9fb3-4030-a5df-7900f78d098a', 3, 'This is coded using the Repair root operation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('802fa804-4154-49b9-9c68-c32a5294f8bf', '8fb3f20a-7f83-4390-9e41-01c2c7279998', 0, 'The pressure ulcer code category, since it''s still an ulcer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e30254a9-72b3-423a-8f0e-7f0cf314c8f0', '8fb3f20a-7f83-4390-9e41-01c2c7279998', 1, 'The specific non-pressure chronic ulcer code category, which is structurally distinct from pressure ulcer codes and requires documentation of laterality, specific leg location, and depth (e.g., limited to breakdown of skin, with fat layer exposed, with necrosis of muscle, with necrosis of bone)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b04938c-34f7-4d46-b9aa-975ff599f872', '8fb3f20a-7f83-4390-9e41-01c2c7279998', 2, 'A generic ''skin lesion, unspecified'' code regardless of the ulcer''s specific documented characteristics');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd378b1d-a95c-4446-a4bd-901f3553da74', '8fb3f20a-7f83-4390-9e41-01c2c7279998', 3, 'The same code category used for a diabetic foot ulcer regardless of documented etiology');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dcaae6f1-e696-4c30-87ff-ba7aa230a2a9', 'fbc37469-79eb-4245-9803-5f30f8276e48', 0, 'ICD-10-CM includes a combination code capturing diabetes with a foot ulcer, PLUS an additional code from the non-pressure chronic ulcer category specifying the ulcer''s exact site/laterality/depth, since the diabetes-ulcer combination code alone doesn''t capture that level of site/depth detail');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9693e684-5805-4448-947a-c08bc71e0636', 'fbc37469-79eb-4245-9803-5f30f8276e48', 1, 'Only the diabetes-ulcer combination code is ever used, with no additional site/depth code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c20664e2-920c-4534-a4a7-c95915c7e217', 'fbc37469-79eb-4245-9803-5f30f8276e48', 2, 'Diabetic foot ulcers are coded identically to non-diabetic non-pressure ulcers with no diabetes linkage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb526773-4dbd-47c9-93a3-4fa5d0c3a6c4', 'fbc37469-79eb-4245-9803-5f30f8276e48', 3, 'Diabetic foot ulcers can never be coded to a specific depth');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c6d65a7-0358-49c1-9a3a-5d35860569bb', '8d99007c-c1e7-4c3c-a330-57034c78ce26', 0, 'Excision, with the subcutaneous tissue body part value reflecting the deepest layer actually debrided, consistent with the depth-dependent debridement coding principle already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4885e76d-ccd6-41aa-b267-f1e6b7bc05f1', '8d99007c-c1e7-4c3c-a330-57034c78ce26', 1, 'Extraction, regardless of the depth or technique used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bcdba2e1-23fe-4cec-92f6-f511851d280a', '8d99007c-c1e7-4c3c-a330-57034c78ce26', 2, 'Debridement of diabetic ulcers is coded identically regardless of depth');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8bf70d72-0bb6-4fff-9035-29de494ffce7', '8d99007c-c1e7-4c3c-a330-57034c78ce26', 3, 'Destruction, since diabetic tissue is being eliminated');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('baa138fa-539e-4ded-9797-882a82114411', '4a53205f-393b-4df5-a7e8-854b7604d431', 0, 'Excision or Resection, depending on whether a portion or an entire lobe/lung is removed, consistent with the general portion-versus-entire distinction already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f11a05ed-24f3-4ff6-8ad7-4b694367ea76', '4a53205f-393b-4df5-a7e8-854b7604d431', 1, 'Restriction, since lung volume is being reduced');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b567f540-95c7-471f-b4c8-4ce00fb89690', '4a53205f-393b-4df5-a7e8-854b7604d431', 2, 'Occlusion, since airways are being closed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d6fbc47-44f0-40a9-a571-53b70fea262c', '4a53205f-393b-4df5-a7e8-854b7604d431', 3, 'Supplement, since lung function is being reinforced');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6de6fb8d-b7e7-4c5a-acb5-9052a7278150', 'a4e5cae7-0e2a-4252-8ba3-6d1d6c703cd9', 0, 'Bypass (altering the route of passage of air, creating an alternate airway route bypassing the upper airway) — many coding references classify tracheostomy creation under Bypass given its function of rerouting the air passage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dbdeb68d-9c7f-4056-ac72-5ef9b40e8e7f', 'a4e5cae7-0e2a-4252-8ba3-6d1d6c703cd9', 1, 'Drainage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('51ba6db0-ceb1-47b9-a606-5907cd8d0e90', 'a4e5cae7-0e2a-4252-8ba3-6d1d6c703cd9', 2, 'Restriction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('166dd470-2da7-466e-a511-4384d898e221', 'a4e5cae7-0e2a-4252-8ba3-6d1d6c703cd9', 3, 'Extraction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5bc3f1d0-244c-42d4-9727-49737c46efaa', 'a7432efc-0c80-40f6-be90-5e9d3401484a', 0, 'ICD-10-PCS includes specific procedure codes reflecting duration ranges of mechanical ventilation (e.g., less than 24 consecutive hours, 24-96 consecutive hours, greater than 96 consecutive hours), meaning accurate documentation of ventilator start/stop times directly affects correct code selection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48e86510-00a7-4008-ab96-9301cf7f59c4', 'a7432efc-0c80-40f6-be90-5e9d3401484a', 1, 'Ventilator duration has no bearing on which ICD-10-PCS code is selected');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbe15e9d-1609-4abb-b551-a774e3e21c93', 'a7432efc-0c80-40f6-be90-5e9d3401484a', 2, 'Only a single universal ventilation code exists regardless of duration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e735427b-51a2-42fd-b4a6-be5c37deb8ee', 'a7432efc-0c80-40f6-be90-5e9d3401484a', 3, 'Ventilator hours are tracked only for nursing purposes, never for coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c1f8f90-8146-4286-85bc-dbd0937b6a98', '7f83c30f-dd4e-4949-bfec-3cdeaffe0e89', 0, 'Only ventilator hours occurring after the formal inpatient admission order count, with ED-initiated ventilation time excluded entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bec2bf1b-3f20-4cac-a64c-ecae92140958', '7f83c30f-dd4e-4949-bfec-3cdeaffe0e89', 1, 'Coding guidance generally directs counting ventilator hours from the initiation of mechanical ventilation (including during a preceding ED encounter that converts directly to inpatient admission for the same episode of care), not solely from the formal inpatient admission timestamp, since the guideline''s intent is to capture the actual duration of ventilatory support provided');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5f92587-5953-4e93-bbad-586178860145', '7f83c30f-dd4e-4949-bfec-3cdeaffe0e89', 2, 'Ventilator hours are calculated based on calendar days, not actual hours, regardless of exact initiation time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8373d61-9dbd-4cab-bda1-9abc5bda6e17', '7f83c30f-dd4e-4949-bfec-3cdeaffe0e89', 3, 'Ventilator duration coding never considers time spent in the Emergency Department under any circumstance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a78d9b3-1c69-483c-91b2-1c904c2dd243', '3eb8500d-6fb8-4bf8-873e-74ee8344549f', 0, 'The appropriate duration-banded ventilator code (e.g., less than 24 consecutive hours) is still assigned reflecting the actual hours of ventilation provided, even though the episode ended due to death rather than successful weaning');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63b918c5-a77a-4d2f-85bb-f2ebf457d8b9', '3eb8500d-6fb8-4bf8-873e-74ee8344549f', 1, 'No ventilator code is ever assigned when the patient dies while ventilated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f0b3422-58ec-41d8-9091-75c0641fa73e', '3eb8500d-6fb8-4bf8-873e-74ee8344549f', 2, 'The next-higher duration band is always used automatically in cases resulting in death, regardless of actual hours');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a95ef1d6-0f00-4617-80c9-dda285f3efbb', '3eb8500d-6fb8-4bf8-873e-74ee8344549f', 3, 'Ventilator coding is skipped entirely whenever the outcome is death');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb8bcec6-a908-4dd4-bc16-ba17f67df0f0', '699ec754-be3e-4847-a2fc-ab748f36aa98', 0, 'Extirpation (taking out solid matter — the calculus — that has no natural or created channel to the outside of the body, at the time of the procedure)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b3945c6-7a3f-4543-a3ef-0a6d1eae10af', '699ec754-be3e-4847-a2fc-ab748f36aa98', 1, 'Excision, since tissue is being removed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3f92c97b-256d-4173-9dc2-48ab0b19af75', '699ec754-be3e-4847-a2fc-ab748f36aa98', 2, 'Drainage, since bile duct fluid is involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d201338-d5ef-41b6-bb8d-9953fbd01f6d', '699ec754-be3e-4847-a2fc-ab748f36aa98', 3, 'Restriction, since the duct is being narrowed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0aa0379e-458b-481c-8a97-ebb0c3598fed', 'ecbf3146-a8af-4ed9-94c5-0a35227820b0', 0, 'Resection, approach open, body part gallbladder — reflecting both the entire-organ-removal principle (Resection, not Excision, since the whole gallbladder is removed) and the approach-actually-completed principle (open, not laparoscopic) already established');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('65adeb2a-7c58-407c-9ea1-2786edf3b495', 'ecbf3146-a8af-4ed9-94c5-0a35227820b0', 1, 'Excision, approach percutaneous endoscopic, body part gallbladder');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dad52ed6-c079-4998-a16c-07e7b6ae0225', 'ecbf3146-a8af-4ed9-94c5-0a35227820b0', 2, 'Resection, approach percutaneous endoscopic, body part gallbladder');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff3f7871-49b5-432f-86d9-4c33c9ce599c', 'ecbf3146-a8af-4ed9-94c5-0a35227820b0', 3, 'Excision, approach open, body part liver');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5c81aea-68ef-473b-bec4-9b93cba643c3', '1aacc497-8252-4b5d-87e3-9f0dd8462ff9', 0, 'Coding pneumonia due to the specific identified organism (a combination code where classification provides one, or pneumonia plus an additional organism code per guideline structure), rather than defaulting to unspecified bacterial pneumonia when the organism is clearly documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39beea6b-3cb4-4455-ad7f-d918378e3aef', '1aacc497-8252-4b5d-87e3-9f0dd8462ff9', 1, 'Always using unspecified pneumonia regardless of documented organism, since organism identification doesn''t affect ICD-10-CM coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f148199a-7a9b-474f-8c56-ebd1624726b7', '1aacc497-8252-4b5d-87e3-9f0dd8462ff9', 2, 'Using a code for the organism alone, with no pneumonia code at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e37f430a-d60f-4719-bfda-fa5e3b169def', '1aacc497-8252-4b5d-87e3-9f0dd8462ff9', 3, 'Organism-specific pneumonia coding applies only to viral pneumonia, never bacterial pneumonia');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d55e0dd0-825b-4c4d-a8a6-bde19a949600', 'ab15c223-c5b7-43e3-a6fe-d9915602a2ec', 0, 'CKD stage 5 is always the principal diagnosis regardless of the actual reason for this admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d829e964-f3fd-44c6-bac5-bdb8649eefe8', 'ab15c223-c5b7-43e3-a6fe-d9915602a2ec', 1, 'The hyperkalemia (or its underlying acute cause, per UHDDS principal diagnosis selection for the reason this specific admission was occasioned) is likely the appropriate principal diagnosis if that is what chiefly necessitated this admission, with CKD stage 5 coded as an additional diagnosis reflecting its ongoing clinical significance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4999e432-ac61-4435-ad60-0338cb4b4234', 'ab15c223-c5b7-43e3-a6fe-d9915602a2ec', 2, 'Hyperkalemia can never be coded as principal diagnosis under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('776c5411-d6dd-4a16-8100-d510d5a6dd33', 'ab15c223-c5b7-43e3-a6fe-d9915602a2ec', 3, 'Only the CKD stage matters; hyperkalemia is never separately coded');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1c43719-4703-46df-88bd-099ac5a5ced9', '70287973-5052-4073-b613-1be3ff6438c8', 0, 'Transplantation root operation for the transplant procedure itself, with the ESRD diagnosis coded, and post-transplant status appropriately reflected going forward (via aftercare/status codes) for future encounters once the transplant is completed and functioning');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30740afd-2b6b-4371-8d73-e591f1aeff28', '70287973-5052-4073-b613-1be3ff6438c8', 1, 'The transplant is coded using the Replacement root operation, since the new kidney replaces the failed one');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eaa4f47d-3401-4cd6-9bd1-1d09eee72b1c', '70287973-5052-4073-b613-1be3ff6438c8', 2, 'ESRD is never coded once a transplant is performed, even during the same admission the transplant occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f73c4c2-3637-42e1-b295-3aaca1a76ba2', '70287973-5052-4073-b613-1be3ff6438c8', 3, 'Kidney transplant recipients require no specific post-transplant status coding for future encounters');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2a4d650-7ee0-461f-bf1c-9f7bba685ac8', '102acad6-c470-48d8-aee7-14eb710fcbe5', 0, 'Donor-source detail has no bearing on ICD-10-PCS coding for kidney transplant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82ffc7a7-10d9-4445-a940-780d6d3dc2a8', '102acad6-c470-48d8-aee7-14eb710fcbe5', 1, 'The donor-source relationship is captured via the qualifier value for the Transplantation root operation, meaning this documented detail directly determines the correct, complete procedure code — consistent with the same donor-source-qualifier principle already established for stem cell transplantation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b99584de-7564-40e3-a588-f9cb78feb1e2', '102acad6-c470-48d8-aee7-14eb710fcbe5', 2, 'Donor source is relevant only for organ allocation purposes, never for coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e02b203b-60a7-4291-89e4-b309d05eaa0f', '102acad6-c470-48d8-aee7-14eb710fcbe5', 3, 'Only deceased-donor transplants are ever coded; living-donor transplants use an entirely different code system');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f09f91bf-7c3e-4199-8076-0d3feb0c5293', '42102ee9-38dd-49ad-b9ff-ada59fc5446a', 0, 'The same duration-banded invasive mechanical ventilation codes used for intubated patients, since BiPAP is ''close enough'' to invasive ventilation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3199570-ae93-4495-815a-b934dac5da8b', '42102ee9-38dd-49ad-b9ff-ada59fc5446a', 1, 'Coding conventions distinguish noninvasive ventilation (e.g., BiPAP/CPAP) from invasive mechanical ventilation, meaning the specific type of respiratory support actually provided (noninvasive vs. invasive) is a documentation detail directly affecting correct code selection, not an interchangeable substitute for one another');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a9e4907-ebc2-450f-9dee-0bf46e11dff1', '42102ee9-38dd-49ad-b9ff-ada59fc5446a', 2, 'BiPAP is never coded under any circumstance, regardless of duration or clinical significance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('442e8ddc-5e53-4c12-985a-d7fa56e88634', '42102ee9-38dd-49ad-b9ff-ada59fc5446a', 3, 'BiPAP and invasive ventilation are always coded identically, with the distinction having no coding significance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8e4c2aa-69af-45de-a852-66f71bc7d784', '6bc8cc98-fdbf-4b36-aa4c-32c730715f98', 0, 'Drainage root operation, with a qualifier reflecting the therapeutic (not diagnostic) nature of the fluid removal, since the purpose is to relieve respiratory distress by removing fluid rather than purely for diagnostic sampling');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8f2325f-079f-4be9-a90c-fcb7a6bab879', '6bc8cc98-fdbf-4b36-aa4c-32c730715f98', 1, 'Extirpation, since fluid is a form of solid matter for coding purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7f0a962-a905-490f-90f7-fe1e76ee5d80', '6bc8cc98-fdbf-4b36-aa4c-32c730715f98', 2, 'Excision, since pleural tissue is involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8cc833bf-e35b-40e6-868a-b3403f41d7f2', '6bc8cc98-fdbf-4b36-aa4c-32c730715f98', 3, 'Restriction, since lung expansion is being restricted by the effusion');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9187103-fb2d-46f6-a3be-e94f532b0a65', 'b9695fef-b352-42dd-9369-0bb2ea44b658', 0, 'Drainage, reflecting the ongoing removal of air/fluid from the pleural space via the tube');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1518da5b-bc8e-4e9a-b03d-9d39ed0bc1fc', 'b9695fef-b352-42dd-9369-0bb2ea44b658', 1, 'Insertion, since a tube is being inserted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('183f2f04-f176-4879-9b14-9834d3cbaa06', 'b9695fef-b352-42dd-9369-0bb2ea44b658', 2, 'Bypass, since air is being rerouted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ee56548-5291-4607-8a69-2ac36ba6e0c6', 'b9695fef-b352-42dd-9369-0bb2ea44b658', 3, 'Restriction, since the pneumothorax is being controlled');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('597ce286-34b4-40d4-b3f7-690a8b9d3691', '8bb19c20-b59e-42ff-bde8-a7d4516a44b3', 0, 'Destruction (eradicating the pleural space''s ability to separate, via chemical/mechanical means) is a commonly used root operation concept for pleurodesis, since the goal is to obliterate/eliminate the potential space rather than remove, repair, or reinforce a body part in the usual sense');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19972318-d8de-4357-9cab-a2230ef74b3a', '8bb19c20-b59e-42ff-bde8-a7d4516a44b3', 1, 'Pleurodesis is coded identically to a simple thoracentesis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d4ce21f-df68-4573-ad3b-48ae4c2738ad', '8bb19c20-b59e-42ff-bde8-a7d4516a44b3', 2, 'Pleurodesis is coded using the Bypass root operation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04b82492-fb27-4bf2-b796-ae776e9a1775', '8bb19c20-b59e-42ff-bde8-a7d4516a44b3', 3, 'Pleurodesis is never separately coded from chest tube placement');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bde51f20-2d17-4457-8614-bb375f407fcf', '29b6e837-bf71-42fa-afe8-0e87a7bfbed7', 0, 'ICD-10-CM includes specific respiratory failure codes capturing acuity (acute, chronic, acute-on-chronic) and type (hypoxemic, hypercapnic, or both combined) when documented, following the same acute-on-chronic and combination-coding principles already established for other conditions like heart failure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('193daa4f-81e1-449d-9978-67c94c65a359', '29b6e837-bf71-42fa-afe8-0e87a7bfbed7', 1, 'Only hypoxemic respiratory failure has a corresponding ICD-10-CM code; hypercapnic respiratory failure is not separately classified');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fabc094c-e31a-4422-a42d-eaa0aed1f791', '29b6e837-bf71-42fa-afe8-0e87a7bfbed7', 2, 'Acute-on-chronic status is never distinguished from purely acute or purely chronic respiratory failure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa6eb1b4-add4-4829-b6a8-ed33e1118642', '29b6e837-bf71-42fa-afe8-0e87a7bfbed7', 3, 'Respiratory failure type (hypoxemic vs. hypercapnic) has no bearing on code selection');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0072fbd5-7712-43ee-a821-6394eaf560bc', '383aa33f-5ed2-440f-9a77-250f16c561b9', 0, 'A specific code for Barrett''s esophagus WITH dysplasia (and the specific grade, when the classification provides that level of detail) should be used, rather than a generic Barrett''s esophagus code without dysplasia when dysplasia has actually been pathologically confirmed and documented');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68266c3a-067f-4b99-aaf8-4ad924a57225', '383aa33f-5ed2-440f-9a77-250f16c561b9', 1, 'Barrett''s esophagus and dysplasia are always coded as entirely separate, unrelated diagnoses');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63204978-9d8f-4d9c-bb51-0bc8292856aa', '383aa33f-5ed2-440f-9a77-250f16c561b9', 2, 'Only the pathology report''s technical language may ever be used, with no physician diagnosis statement needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c2550bc-6174-4a45-9495-273d74770d2c', '383aa33f-5ed2-440f-9a77-250f16c561b9', 3, 'Dysplasia grade is never a coding element for Barrett''s esophagus');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5d6b76e-124f-4105-bb79-b50dd5952759', 'c2fc06ce-f9bc-4dd3-9bc9-6c233d73a7ae', 0, 'Occlusion (completely closing an orifice/lumen — here, occluding blood flow through the varix via the band) is the most likely applicable root operation, reflecting the mechanism of controlling bleeding by cutting off blood flow to the varix');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('379e95ad-effc-4ba4-b8be-d772d91c3d03', 'c2fc06ce-f9bc-4dd3-9bc9-6c233d73a7ae', 1, 'Restriction, since the esophagus itself is being narrowed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('474de52d-ffa6-44e6-a05e-c699905f20a1', 'c2fc06ce-f9bc-4dd3-9bc9-6c233d73a7ae', 2, 'Excision, since varix tissue is removed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3c27eb3-5819-4cde-abf6-84ed09f338b2', 'c2fc06ce-f9bc-4dd3-9bc9-6c233d73a7ae', 3, 'Bypass, since blood flow is rerouted');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2fb89106-5a99-42c8-9868-2b5455aca330', '3fc8ce96-1e36-4676-b1b7-f1128e06fa0c', 0, 'The esophageal varices with bleeding (the acute condition occasioning this specific admission), with cirrhosis coded as an additional diagnosis reflecting the underlying chronic liver disease');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27413917-df8b-44fd-b799-3555f4b28020', '3fc8ce96-1e36-4676-b1b7-f1128e06fa0c', 1, 'Cirrhosis is always the principal diagnosis regardless of the acute reason for this admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5fc0eaa2-28b9-4ec9-8f46-4e778976ad17', '3fc8ce96-1e36-4676-b1b7-f1128e06fa0c', 2, 'Only the bleeding symptom is coded, with neither varices nor cirrhosis coded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0d3e375-6950-45a6-b86e-d51b8ee8d5db', '3fc8ce96-1e36-4676-b1b7-f1128e06fa0c', 3, 'Esophageal varices and cirrhosis are always combined into one single code with no distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('509136f4-ca0c-4d89-be4c-6b83f4ed4bb4', 'bd52d9f9-6e74-4a36-9e7d-a8b1b3ab569d', 0, 'ICD-10-CM includes a specific code for hepatic encephalopathy (with a ''code first'' or ''use additional code'' instructional convention typically linking it to the underlying liver disease), reflecting the etiology/manifestation combination-coding principle already covered generally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64afa710-5bcc-4fc4-b887-1f7077b92f67', 'bd52d9f9-6e74-4a36-9e7d-a8b1b3ab569d', 1, 'Hepatic encephalopathy is coded using a generic altered-mental-status code with no link to the underlying liver disease');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af0e0887-05c5-489a-8622-fe44011cb759', 'bd52d9f9-6e74-4a36-9e7d-a8b1b3ab569d', 2, 'Hepatic encephalopathy can never be coded as an additional diagnosis alongside cirrhosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9f8feb43-06d2-4d4a-ae3d-56c7c55431b9', 'bd52d9f9-6e74-4a36-9e7d-a8b1b3ab569d', 3, 'Hepatic encephalopathy is coded identically regardless of whether cirrhosis is documented');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b44a936a-30a1-4845-95fd-71470d6541fc', '26b87353-2b10-4c6a-96c4-5cb073c3e415', 0, 'Drainage, with a therapeutic qualifier, reflecting fluid removal from the peritoneal cavity for symptomatic relief rather than purely diagnostic sampling');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7aad797e-983f-49ff-af08-9dcd593fabba', '26b87353-2b10-4c6a-96c4-5cb073c3e415', 1, 'Extirpation, since ascitic fluid is treated as solid matter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('65a1c4a2-220e-4eee-9405-1ea8e2fc123c', '26b87353-2b10-4c6a-96c4-5cb073c3e415', 2, 'Excision, since peritoneal tissue is involved');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('550bf586-82a8-4042-9d04-b2434b49ac2f', '26b87353-2b10-4c6a-96c4-5cb073c3e415', 3, 'Restriction, since the peritoneal cavity is being narrowed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b950b32c-98c1-4ec6-9f94-749bdb34caf9', '4917bcb6-51fa-48c3-9c1f-2d534b047c9f', 0, 'SBP has its own specific ICD-10-CM code reflecting this distinct clinical entity (an infection of ascitic fluid without an evident intra-abdominal surgical source), separate from generic peritonitis codes used for other causes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da824e4e-bfb7-41ee-98f8-1cbefaf7985e', '4917bcb6-51fa-48c3-9c1f-2d534b047c9f', 1, 'SBP is coded identically to peritonitis following a surgical procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae6caf14-5262-4a39-a849-d87ad8fc9f38', '4917bcb6-51fa-48c3-9c1f-2d534b047c9f', 2, 'SBP is never separately coded from generic ascites');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b009a01-8bd2-49fa-9a73-0f9909bf904d', '4917bcb6-51fa-48c3-9c1f-2d534b047c9f', 3, 'SBP can only be coded if a laparotomy is performed to confirm it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14b40d93-1ac9-47aa-b7b1-98c7a8017797', 'd835a454-ea0b-476e-a342-6c2c9665aaae', 0, 'Bypass, reflecting the creation of a new route for blood flow (altering the route of passage) between the portal and hepatic venous systems, consistent with the Bypass root operation''s core definition already applied to CABG and AV fistula creation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c43df615-0c27-442b-b530-f7ad709f1322', 'd835a454-ea0b-476e-a342-6c2c9665aaae', 1, 'Restriction, since portal pressure is being restricted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc73b237-7a41-49ee-88ce-619a65a57f75', 'd835a454-ea0b-476e-a342-6c2c9665aaae', 2, 'Occlusion, since blood flow is being closed off');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f939482e-893c-4755-a068-e31ee4dc5656', 'd835a454-ea0b-476e-a342-6c2c9665aaae', 3, 'Dilation, since a vessel is being widened');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9cae5902-32e0-4850-affc-dfc03abfe79c', '6b50f3d1-5ac5-47dd-8289-be1c515bd644', 0, 'Both the specific alcohol-related liver disease code (reflecting the specific liver condition, e.g., alcoholic cirrhosis) AND the alcohol use disorder code with its documented severity, since these represent two distinct, separately classified conditions that are both coded when both are clinically relevant');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fdc49d29-6ee0-4a18-82d4-af85a13a44f2', '6b50f3d1-5ac5-47dd-8289-be1c515bd644', 1, 'Only the liver disease code, with alcohol use disorder never separately coded when liver disease is present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8195e5f-1434-48a9-830b-a1afe23d0a8f', '6b50f3d1-5ac5-47dd-8289-be1c515bd644', 2, 'Only the alcohol use disorder code, with the specific liver disease left uncoded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dea6cb3-eb5e-43ec-a541-b3cc81a1948b', '6b50f3d1-5ac5-47dd-8289-be1c515bd644', 3, 'A single combined code exists capturing both conditions with no need for two separate codes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53d4167c-27c3-40ff-b6d2-10ec62c77bdc', 'd91f9724-4b58-4575-b969-d01be155191c', 0, 'Excision, approach percutaneous, body part liver, with the diagnostic qualifier — reflecting a portion of tissue removed for diagnostic purposes via a percutaneous (needle) approach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88083f6c-ae05-46b4-a493-2a06d92ab271', 'd91f9724-4b58-4575-b969-d01be155191c', 1, 'Resection, since the entire liver is being evaluated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67d2fabb-f16f-46e0-83f9-c68113361d06', 'd91f9724-4b58-4575-b969-d01be155191c', 2, 'Extraction, since a needle is used');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('827790cb-be91-4d2b-8a11-4b67b15fdca6', 'd91f9724-4b58-4575-b969-d01be155191c', 3, 'Drainage, since liver tissue contains blood');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36772308-fa45-45e3-a00a-13302a33f01b', 'ff6cbbf3-f9f4-462d-a864-6d2a31b991c1', 0, 'The GI bleed/duodenal ulcer (the underlying cause, once identified, that is chiefly responsible for the admission after study) is generally the appropriate principal diagnosis, with anemia coded as an additional diagnosis, consistent with UHDDS''s ''established after study'' principle even when the initial presenting problem (anemia) wasn''t yet specifically diagnosed at the time of admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad7806f6-6d4d-4247-86dc-12c3355a7ec4', 'ff6cbbf3-f9f4-462d-a864-6d2a31b991c1', 1, 'Anemia is always the principal diagnosis regardless of what is discovered during the workup');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e68913e8-e7e1-4d50-8082-bcf6af7f5bff', 'ff6cbbf3-f9f4-462d-a864-6d2a31b991c1', 2, 'The duodenal ulcer is never coded once anemia has already been documented as a reason for admission');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fa908b4-e480-4023-82b1-6fb3fda675df', 'ff6cbbf3-f9f4-462d-a864-6d2a31b991c1', 3, 'Only the EGD procedure is coded, with no diagnosis code for either anemia or the ulcer');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c30d0cdd-1912-41e1-ab2c-1c4574b90538', '71372ce3-9c62-49d5-9860-531f7664c6b5', 0, 'Both the acute kidney injury AND the chronic kidney disease (with its specific stage, when documented) are coded as separate, distinct diagnoses, since ICD-10-CM does not have a single combination code capturing ''AKI on CKD'' the way it does for some other acute-on-chronic conditions (like heart failure or respiratory failure)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5d25241-4557-485f-839e-1a27a7feb39b', '71372ce3-9c62-49d5-9860-531f7664c6b5', 1, 'AKI and CKD are always combined into a single code, with no need to code both separately');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('766c701f-29d1-467a-9579-7eb671866664', '71372ce3-9c62-49d5-9860-531f7664c6b5', 2, 'Only the CKD stage is coded; AKI is disregarded whenever CKD is also present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc7f6108-fab7-400f-b864-3731291c97a6', '71372ce3-9c62-49d5-9860-531f7664c6b5', 3, 'AKI can never be coded when CKD is already documented');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9db139f4-1924-4b00-8ac2-689f05097613', 'ca665edd-f34c-4de2-950e-e0aee20bf6c1', 0, 'Both the specific malignant neoplasm of liver code AND the cirrhosis code are reported, since these are distinct, separately classified conditions both clinically significant to the patient''s care, with sequencing determined by the reason for the specific encounter (UHDDS principal diagnosis principle)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee195a24-774c-42f0-b05f-3aef5dc08db2', 'ca665edd-f34c-4de2-950e-e0aee20bf6c1', 1, 'Only the malignancy is coded; cirrhosis is always disregarded once cancer develops');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2faac2db-b706-4fd8-800d-d4be2a8a1274', 'ca665edd-f34c-4de2-950e-e0aee20bf6c1', 2, 'Only cirrhosis is coded; the malignancy is considered part of the cirrhosis code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8fd44399-3405-42a2-9a50-a6407b3fda1e', 'ca665edd-f34c-4de2-950e-e0aee20bf6c1', 3, 'The two conditions are combined into a single code with no distinction');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('72f0f562-9e57-4f7f-94ee-39f5ec600cee', '96019de2-dfde-4ead-ad12-d4f151ec1e69', 0, 'Assume the prior encounter''s access type still applies without any current verification, since access type rarely changes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a543b7c4-db09-4f51-b659-d3a70eeb5888', '96019de2-dfde-4ead-ad12-d4f151ec1e69', 1, 'Recognize that dialysis access type can change over time (fistula failure requiring conversion to a graft or catheter, for example), so current-encounter documentation (or a query, if access-type-specific coding is actually needed for this encounter) should establish the CURRENT access type rather than assuming continuity from a prior encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a650d53-4853-4477-8860-1b6013c92055', '96019de2-dfde-4ead-ad12-d4f151ec1e69', 2, 'Access type is never a coding-relevant detail regardless of clinical procedures performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91cebd5f-1c12-464d-8842-8b65b07627cf', '96019de2-dfde-4ead-ad12-d4f151ec1e69', 3, 'Only nephrology notes, never nursing dialysis flow sheets, may ever document access type');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5091ef5f-43b2-4f86-8d54-2bd792192384', '4b1d7124-bdf7-48e9-a9de-c9f5af5fd54a', 0, 'Adequate documentation, since ''removed'' is sufficient regardless of technique');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ede341d-31fa-4a12-bfbc-d989a6bc4491', '4b1d7124-bdf7-48e9-a9de-c9f5af5fd54a', 1, 'A potential specificity gap, since different removal techniques map to different root operations (Excision vs. Destruction, as already established) — the operative report should ideally specify technique per polyp/site, and a query may be needed if the distinction can''t be resolved from the full report');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2348589c-3a12-4452-9b28-2f132fd0fcb6', '4b1d7124-bdf7-48e9-a9de-c9f5af5fd54a', 2, 'Grounds to code every polyp as removed via Destruction by default');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3915808b-46c7-4657-a332-ee918bfaeb54', '4b1d7124-bdf7-48e9-a9de-c9f5af5fd54a', 3, 'Grounds to refuse coding any of the polyps');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f7c0e0dd-b00b-4672-935e-f6b65f21aad2', 'c9298060-3cba-4d41-b412-b20ed0f24e15', 0, 'Assume continuous ventilation for the entire stay regardless of documentation gaps');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12d9b242-14c1-4e24-89c0-d785fc4789e6', 'c9298060-3cba-4d41-b412-b20ed0f24e15', 1, 'Review all available respiratory therapy/nursing documentation (flow sheets, respiratory therapy notes, physician orders for ventilator initiation/discontinuation) to reconstruct the most accurate total duration possible, recognizing that documentation gaps in one specific source (the flow sheet) don''t necessarily mean ventilation didn''t continue — cross-referencing other sources is the appropriate first step, with a query used if genuine ambiguity remains after that review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7832247-5e50-4488-81d2-f4fd911e63f0', 'c9298060-3cba-4d41-b412-b20ed0f24e15', 2, 'Use only the flow sheet with gaps, coding the shortest possible duration band regardless of other documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89ff7249-9f38-413e-8883-6389a093b432', 'c9298060-3cba-4d41-b412-b20ed0f24e15', 3, 'Ventilator duration can never be coded when any documentation gap exists, however minor');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a9d7081-17b9-42ce-b501-66d3da59af77', 'ca46e6cb-bdb3-4179-baca-13c69cf6c4cb', 0, 'Code the ulcer as an unspecified type, ignoring the vascular surgery consult''s etiology documentation entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('59768332-f35e-40ea-bda2-78d2398d2077', 'ca46e6cb-bdb3-4179-baca-13c69cf6c4cb', 1, 'Recognize that the vascular surgery consult''s etiology documentation is directly relevant and should be incorporated when determining the correct ulcer code category — reviewing across all provider documentation for the same episode, not limiting review to a single wound-care-specific note, since etiology determination often comes from a different specialist''s documentation than the wound description itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('880fac76-73db-4909-9b71-f86db8f5db43', 'ca46e6cb-bdb3-4179-baca-13c69cf6c4cb', 2, 'Query is always mandatory even when another provider''s note already establishes the etiology clearly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae9a20b6-55e4-4bcf-a7b5-30b196974694', 'ca46e6cb-bdb3-4179-baca-13c69cf6c4cb', 3, 'Etiology can only ever be established by the wound care provider specifically, never a vascular surgeon');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb271647-5ce9-4e09-826d-b42e67c189a9', '2428fbc1-7bd8-4616-94ca-33008b5fa578', 0, 'The pathology finding is irrelevant to coding since it wasn''t known during the actual procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('516bb67c-25ea-46d2-9ba2-512d4ccba20c', '2428fbc1-7bd8-4616-94ca-33008b5fa578', 1, 'The pathology report is a legitimate, important documentation source that should be incorporated into coding once available (e.g., potentially affecting the specificity of a lesion/polyp diagnosis code), since coding for procedures often appropriately awaits or is amended based on the final pathology result rather than being limited to only what was known intraoperatively');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ad4a0e7f-8737-4577-b8fe-5b44ba8d6f1c', '2428fbc1-7bd8-4616-94ca-33008b5fa578', 2, 'Only the original procedure note may ever be used; pathology reports are categorically excluded from coding consideration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2da811de-3e3d-453f-9a59-9bfe94c883dc', '2428fbc1-7bd8-4616-94ca-33008b5fa578', 3, 'Pathology findings can only be incorporated if the original surgeon personally re-dictates the operative note');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8db0f84e-cb79-4d29-87de-103a26bb8dd9', 'd5cb09d0-0f02-4da6-9559-ec15781fb451', 0, 'Code based on the brief nursing note alone as if it were the full operative documentation, assigning specific root operations/techniques not actually described in that note');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cdefe0c4-4855-44f5-acec-992a5bbb0dc8', 'd5cb09d0-0f02-4da6-9559-ec15781fb451', 1, 'Hold coding until the physician''s own dictated procedure note (or equivalent detailed documentation) becomes available, since the specific technique/root operation/site details needed for accurate ICD-10-PCS coding are not present in a brief nursing note alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc34cc88-bfb5-4637-bb80-fc484d833ed0', 'd5cb09d0-0f02-4da6-9559-ec15781fb451', 2, 'Assign a generic ''colonoscopy, unspecified'' code permanently, with no follow-up once the full note becomes available');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68f0795d-d5d4-4a28-8d25-2cd74b0bb371', 'd5cb09d0-0f02-4da6-9559-ec15781fb451', 3, 'Query the physician immediately, before ever checking whether the note is simply pending completion in the normal course of documentation workflow');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df299da4-8707-4c20-aa4c-dbdab3379751', 'a1dc2c49-2a0d-48c7-8894-257d22cf251f', 0, 'Assume a default duration category without any further chart review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('406b72d7-b1b6-40e6-b4a8-1f178239dbcb', 'a1dc2c49-2a0d-48c7-8894-257d22cf251f', 1, 'Review anesthesia records, ED documentation, or ICU admission notes that may document the actual initiation time, since ventilator initiation is often documented in a different part of the record than the weaning/extubation note — reviewing across these sources before concluding the information is genuinely unavailable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a20a766-54ba-4ed9-a772-a051da5e1785', 'a1dc2c49-2a0d-48c7-8894-257d22cf251f', 2, 'Use only the extubation note''s timestamp as both start and end time, resulting in zero calculated ventilator hours');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e2a0d36-aeef-417c-b045-c7ca5f4fae17', 'a1dc2c49-2a0d-48c7-8894-257d22cf251f', 3, 'Ventilator duration can never be determined once a weaning note exists without a separately documented start time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2605451d-c8fb-48ff-985f-5e0a01a54f54', 'c744f7e2-2f03-4a2e-8406-e3094be84a19', 0, 'Assume therapeutic intent by default for any drainage procedure regardless of documented purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2fce5bc-a864-496d-a44d-05df576d6a7e', 'c744f7e2-2f03-4a2e-8406-e3094be84a19', 1, 'Review the procedure note/indication documentation for the actual stated PURPOSE of the fluid removal (symptomatic relief vs. diagnostic sampling only) — since this documented intent, not the mere fact that fluid was removed, determines the correct qualifier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12604012-bee0-4421-b5b6-bcc83d8ef06b', 'c744f7e2-2f03-4a2e-8406-e3094be84a19', 2, 'The diagnostic-versus-therapeutic distinction is never actually documented and must always be guessed by the coder');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fbf4fc57-dc2e-4f44-855e-df5d3124dcc9', 'c744f7e2-2f03-4a2e-8406-e3094be84a19', 3, 'Only nursing documentation, never the physician''s own procedure note, can establish diagnostic vs. therapeutic intent');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('180b0304-e915-4310-a618-cd432cd501e7', 'b6060d3a-9f42-4de4-9e3e-06ff398ca662', 0, 'Timing documentation for medical screening exams has no relevance to EMTALA compliance whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('117423cf-3df4-4115-9dab-fd4081f0a472', 'b6060d3a-9f42-4de4-9e3e-06ff398ca662', 1, 'Complete EMTALA-relevant documentation (including timing of key events like triage, screening exam, and any transfer decision) supports the facility''s ability to demonstrate compliance if ever reviewed — a documentation-completeness gap here is worth noting/flagging through appropriate channels, even though it isn''t itself a diagnosis/procedure coding accuracy issue');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb5241a7-79e6-41ef-9272-132f3803862d', 'b6060d3a-9f42-4de4-9e3e-06ff398ca662', 2, 'This documentation gap must always be resolved by coding staff personally interviewing the ED physician before any other work can proceed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('22c4137f-e386-44d4-88a5-0e2acb4260f5', 'b6060d3a-9f42-4de4-9e3e-06ff398ca662', 3, 'EMTALA timing documentation is solely an IT system timestamp function requiring zero human documentation practice');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9008a84f-c5eb-4bad-af95-d4ae504c79c6', '34700deb-c807-47e9-9ebc-9ea538eb3fc7', 0, 'HIM staff should refuse all surveyor record requests without prior legal department approval for each individual record');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44aa9951-84e6-4799-b820-7eabb6ca7056', '34700deb-c807-47e9-9ebc-9ea538eb3fc7', 1, 'HIM staff should follow the facility''s established, pre-existing policy/procedure for responding to accreditation survey record requests (which typically involves designated staff facilitating appropriate, compliant access) — having such a policy in place, and staff trained on it, supports smooth survey response rather than improvised handling');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38acaa41-50fd-4755-be07-6c430ce07f04', '34700deb-c807-47e9-9ebc-9ea538eb3fc7', 2, 'Surveyors are never permitted to review any patient health records under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64ba1368-ae77-41e5-b977-02e0a0526c4b', '34700deb-c807-47e9-9ebc-9ea538eb3fc7', 3, 'Only the facility''s CEO personally may respond to any surveyor request');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c696ca22-0caa-46d4-8c47-404b36257289', 'c307b559-58ef-4d02-af5a-e336b59a453e', 0, 'Automatically assume telehealth documentation is held to a lower standard and accept the brief note without further review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78757ed5-8e4d-4ce5-8cad-8413c74468bc', 'c307b559-58ef-4d02-af5a-e336b59a453e', 1, 'Apply the same documentation-sufficiency review already used for in-person visits — if the telehealth note doesn''t adequately support the level/specificity being reported, this is a genuine documentation-completeness gap requiring the same kind of follow-up (further documentation, correction, or physician education) as an inadequately-documented in-person visit would require');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed39747b-64a3-4eff-8ab5-55afbb47f22a', 'c307b559-58ef-4d02-af5a-e336b59a453e', 2, 'Telehealth visits can never be coded at more than the lowest possible E/M level, regardless of actual documented complexity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('10137ad4-1454-4ca4-87e9-b362330f5c2b', 'c307b559-58ef-4d02-af5a-e336b59a453e', 3, 'Only video-based telehealth documentation is ever reviewed for sufficiency; audio-only telehealth documentation requires no review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c8d536b-f44f-4930-aead-4bda889cc2e4', 'aa4a5687-4212-439f-bf05-37577ed4bfe4', 0, 'No documentation-integrity concern exists; device data requires no clinician follow-up documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07bf3c37-749a-45f6-b10d-355427b89d56', 'aa4a5687-4212-439f-bf05-37577ed4bfe4', 1, 'This represents a potential care-gap/documentation-integrity concern worth flagging — an abnormal RPM reading with no documented clinical review/response may indicate either an overlooked clinical signal or simply a device/transmission artifact, and the distinction matters both for patient safety and for whether/how this data should factor into any subsequent diagnosis coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c67ad470-7eba-41d9-b3de-2f06d491a190', 'aa4a5687-4212-439f-bf05-37577ed4bfe4', 2, 'The abnormal reading should automatically be coded as a new diagnosis without any clinical review');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd46d54c-6cff-409d-808a-0e27c216cd6a', 'aa4a5687-4212-439f-bf05-37577ed4bfe4', 3, 'RPM data is never relevant to any documentation-integrity consideration, being purely a technical/IT data stream');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c999c37d-a3a6-47b2-988b-ab5a74e864f5', 'dad6caca-eb01-4902-930e-0d7f498f56aa', 0, 'Automatically code H. pylori as the cause of all documented ulcers, regardless of which one(s) were actually biopsied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('188d484e-be67-4001-98c0-4bfcc2c6312a', 'dad6caca-eb01-4902-930e-0d7f498f56aa', 1, 'Recognize the genuine ambiguity about whether the H. pylori finding applies to just the biopsied ulcer or all documented ulcers, and review further documentation or query the physician for their own clinical determination, rather than the coder independently extrapolating the finding to unbiopsied sites');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff0be40a-c04a-43a6-ad52-b00ddc4196a2', 'dad6caca-eb01-4902-930e-0d7f498f56aa', 2, 'Ignore the H. pylori finding entirely since it applies to only one biopsy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b9c1c80-1b4b-4c49-935b-dcf8735f516d', 'dad6caca-eb01-4902-930e-0d7f498f56aa', 3, 'Code only the pathology report''s finding, disregarding the endoscopy report''s description of multiple ulcers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a182e51-0b1e-4c56-8ba0-0e0bd6e365e7', '18e5a792-e79f-4cbc-a18f-d28723bae903', 0, 'Automatically use whichever source uses more favorable/higher-value terminology for coding purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e99d65a6-ff26-44b9-bbab-4b74706f917a', '18e5a792-e79f-4cbc-a18f-d28723bae903', 1, 'Recognize that terminology variation between different documentation sources describing the SAME underlying donor relationship doesn''t necessarily represent a genuine clinical conflict — reviewing both sources together to confirm they describe the same actual donor-source fact (rather than assuming a real conflict exists) is the appropriate first step before considering a query');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a9b57ee-6d62-43a3-a626-c15f3f224406', '18e5a792-e79f-4cbc-a18f-d28723bae903', 2, 'Always default to the operative note''s terminology, disregarding transplant coordinator records entirely, regardless of clarity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b0da88b-cf2e-4c3a-98d3-aeaca0e4706a', '18e5a792-e79f-4cbc-a18f-d28723bae903', 3, 'Assume any terminology variation always represents a genuine, unresolvable documentation conflict requiring an immediate query with no further review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('129269d5-9cb1-4084-93c0-4d50cd5c7733', 'c486e1ea-6093-411d-a499-086776460d61', 0, 'Interpreter-assisted encounters require no different documentation consideration than any other encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4b012f3-1958-4ff7-8f24-629f3d6cfc75', 'c486e1ea-6093-411d-a499-086776460d61', 1, 'Documentation should ideally reflect that qualified interpreter services were used (supporting both quality-of-care and compliance considerations), and the same general principle of ensuring documented findings genuinely and accurately reflect the clinical encounter applies regardless of whether an interpreter was involved — a coder relying on that documentation should apply the same general documentation-review diligence as with any other encounter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4201a2d5-f25f-4435-bba4-e334d43ae232', 'c486e1ea-6093-411d-a499-086776460d61', 2, 'Interpreter-assisted encounters can never be coded due to inherent communication uncertainty');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f56badfa-f300-4add-8d78-61aa47aefc3e', 'c486e1ea-6093-411d-a499-086776460d61', 3, 'Only family-member interpretation, never professional interpreter services, is relevant to documentation practice');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('128d6b7a-8a7e-4942-9d4c-bc47254ea80a', '98236ac2-cc6f-4572-bb05-0c9f2758598f', 0, 'Automatically code a diagnosis based on the screening score alone, without physician review/incorporation into their own clinical assessment');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f5a7bcb-9cc5-4f22-94f2-0b1d4b3dfb0a', '98236ac2-cc6f-4572-bb05-0c9f2758598f', 1, 'Recognize that patient-reported screening tool results are valuable clinical input but generally require physician review/clinical correlation (similar to other objective data discussed) before being used to support a new diagnosis code — an unaddressed screening result is a potential care-gap/documentation-integrity signal worth noting, not itself sufficient to independently support a diagnosis');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bc169f9-3f30-4f44-b7e5-934ce480e209', '98236ac2-cc6f-4572-bb05-0c9f2758598f', 2, 'Screening tool results are never relevant to documentation or coding under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0bdd23ab-b7fc-4eba-8823-5ac3be6094b9', '98236ac2-cc6f-4572-bb05-0c9f2758598f', 3, 'Only paper-based screening tools, never electronic/portal-based ones, are ever relevant to documentation review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d86dbb0-dd79-4c1f-9053-384273ce2699', 'a0739e2d-3883-4661-8f75-e92d93949f25', 0, 'This is not truly a documentation conflict requiring resolution — it reflects the normal diagnostic process where an initial clinical impression (upper GI bleed, based on presentation) is revised based on subsequent diagnostic findings (a normal EGD ruling out upper GI source, with colonoscopy identifying the actual lower GI source) — the FINAL, diagnostic-test-confirmed determination should generally govern coding, not the earlier clinical impression');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91ea8846-d575-42ea-ad0d-af44366c55b9', 'a0739e2d-3883-4661-8f75-e92d93949f25', 1, 'The ED note''s initial impression must always be used regardless of subsequent, more definitive diagnostic findings');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8ca4d7c9-bcda-4e62-898a-d4db5aae8355', 'a0739e2d-3883-4661-8f75-e92d93949f25', 2, 'Both an upper and lower GI bleed must always be coded together whenever this sequence of events occurs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('581ebff3-bff5-4055-8f66-3ee4b2917cdc', 'a0739e2d-3883-4661-8f75-e92d93949f25', 3, 'This scenario can never be resolved without a formal query, even when the diagnostic workup itself clearly resolves the question');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f0e93fc-e9be-4fc5-903b-40f996af0500', '9eef25ef-a8d2-46cd-8a1f-85d1aab63f58', 0, 'Accept the CAC tool''s single suggested code for the entire procedure without reviewing whether it appropriately captures each distinct technique/site');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7dc570f2-a128-4189-9d24-8fe0db81a927', '9eef25ef-a8d2-46cd-8a1f-85d1aab63f58', 1, 'Given that different techniques at different sites may require different root operations (as already established), a coder should carefully verify that CAC-suggested codes appropriately capture each distinct technique/site combination actually documented, rather than assuming a single suggested code adequately represents a procedure involving genuinely multiple, distinct techniques');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e726570d-ec12-4101-bfd7-2180655cb159', '9eef25ef-a8d2-46cd-8a1f-85d1aab63f58', 2, 'CAC tools are prohibited from being used for any multi-technique procedure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a80ff206-612c-4549-82f1-5d960eb5ab86', '9eef25ef-a8d2-46cd-8a1f-85d1aab63f58', 3, 'Multi-technique procedures can never be accurately coded regardless of CAC assistance or manual review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('637abbca-f6ac-41b0-a781-e0a1645c9705', '070b844f-2ae6-4760-805d-a4e0ebb47405', 0, 'Stent covering type has no bearing on ICD-10-PCS device value selection for TIPS');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a1ed6b3-785a-46f2-a2ad-830b44e9bec9', '070b844f-2ae6-4760-805d-a4e0ebb47405', 1, 'The operative/procedure report should specifically document the type of stent/device used (covered vs. uncovered), since — consistent with the device-specificity documentation principle already established for cardiac and other stents — this detail may determine the correct, complete device value for the procedure code');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b537824-8c88-45ce-bb71-04b644d2f96c', '070b844f-2ae6-4760-805d-a4e0ebb47405', 2, 'Device covering type is assumed to always be ''covered'' by default for all TIPS procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48fd2fd9-0b7c-4e80-ab8e-89089e66e8dd', '070b844f-2ae6-4760-805d-a4e0ebb47405', 3, 'Only the interventional radiology suite''s inventory log, never the physician''s own procedure note, is relevant to device-type documentation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c9572004-081b-4948-a678-030870c50956', '332c8964-a9d3-4de1-ac01-dae32cc650e5', 0, 'Assume hemodialysis based solely on the older note without any current verification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d4d2e99-7dd6-4778-bb70-bd6d3b903d7b', '332c8964-a9d3-4de1-ac01-dae32cc650e5', 1, 'Review current dialysis flow sheets/nursing documentation for the actual modality being used during the CURRENT encounter, since dialysis modality can change over time (as already established) and a vague ''continue current regimen'' note doesn''t itself confirm which specific modality is currently in use');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ddfcabc-9bbb-4918-9c35-d9840ca2cea9', '332c8964-a9d3-4de1-ac01-dae32cc650e5', 2, 'Modality is never relevant to which ICD-10-PCS section/codes apply to dialysis procedures');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a009028-3feb-4ae9-8dd6-5b1ad1cb643f', '332c8964-a9d3-4de1-ac01-dae32cc650e5', 3, 'Only the original nephrologist who started dialysis months ago may ever document current modality');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c41abdb5-84d5-4bf3-9489-6c384f890525', 'd8b6f400-99ca-431d-a50e-7fdfe86ece61', 0, 'A query presenting the clinical context and asking the physician to specify the current access type (fistula, graft, or catheter) from genuine options, rather than presuming one specific type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf11f95f-491f-4542-8c67-453436a0c5f5', 'd8b6f400-99ca-431d-a50e-7fdfe86ece61', 1, 'A query stating ''please confirm the patient has an AV fistula'' with only a yes/no option');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7798a4af-d2a0-4933-9e6c-75f65d7d0646', 'd8b6f400-99ca-431d-a50e-7fdfe86ece61', 2, 'No query should ever be sent regarding dialysis access type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('625dd92f-8da4-44f1-959b-b18c60e8c2b5', 'd8b6f400-99ca-431d-a50e-7fdfe86ece61', 3, 'A query directed to the dialysis center''s billing department rather than the treating physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c3ec920-7985-4cb2-958e-0e6381b6d278', '6c8010e2-f370-44a7-8f26-227ff4b8bf73', 0, 'A non-leading query asking the performing physician to specify the actual technique used for each polyp/site, since this is a fact the performing physician would know with certainty and which directly determines correct root operation coding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ab413c18-4511-4d07-8d9e-1752664fc5e9', '6c8010e2-f370-44a7-8f26-227ff4b8bf73', 1, 'Assume snare technique by default for all colon polyps without querying');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f13bddb-6fee-41dc-bab8-de5cb0d1e944', '6c8010e2-f370-44a7-8f26-227ff4b8bf73', 2, 'Technique is never queryable since it''s considered a purely technical detail beneath query-worthy significance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('831cb889-67bc-4152-947f-2abf66fe4983', '6c8010e2-f370-44a7-8f26-227ff4b8bf73', 3, 'Only the pathologist, never the endoscopist, may be asked to clarify removal technique');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('48d3c4b1-e946-45b3-bc43-565ea11ec5f9', 'a0d067f4-9021-4b81-b9de-d448a092a779', 0, 'A query to the treating physician or respiratory therapy asking them to clarify/reconstruct the actual total duration of ventilatory support based on their own records/knowledge of the case, since this is a factual question about what actually occurred, appropriate for query resolution when documentation review alone doesn''t resolve it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d393128e-1b6d-46d9-a6d9-7e7cf0a0684c', 'a0d067f4-9021-4b81-b9de-d448a092a779', 1, 'Ventilator duration should never be queried since it''s considered purely a nursing/RT administrative matter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27fe6b99-a625-4e9b-a4f9-965362b6f788', 'a0d067f4-9021-4b81-b9de-d448a092a779', 2, 'Always default to the shortest possible duration band without querying, regardless of clinical likelihood');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd6acba8-d3fb-406c-bd05-0f5037fb0db7', 'a0d067f4-9021-4b81-b9de-d448a092a779', 3, 'Only the hospital''s biomedical engineering department may be asked about ventilator duration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3742e81-6840-44ec-b7f8-497b960cbf54', 'db842ca4-d512-4691-b785-1779ea65293d', 0, 'A query presenting the documentation gap and asking the endoscopist to specify the actual technique used per polyp/site, offering the genuine technique options rather than presuming one specific method');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b412bb0a-3b28-4d37-8bb3-e82dd620a14b', 'db842ca4-d512-4691-b785-1779ea65293d', 1, 'A query stating ''please confirm snare technique was used'' with only a yes/no option');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6c044a58-e6b8-4a88-9b43-c0ecd2b56a3f', 'db842ca4-d512-4691-b785-1779ea65293d', 2, 'No query should be sent since technique is considered too minor a detail to query');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b90ce2d7-d00f-4b3b-bffb-677ba4fc502a', 'db842ca4-d512-4691-b785-1779ea65293d', 3, 'A query directed to the GI lab''s equipment inventory log instead of the performing physician');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54407cbd-b4b7-44bb-87cb-ed93a0e4461e', 'd2e5a6fe-edd1-421d-b8f7-67d21f9e1037', 0, 'A non-leading query asking the transplant team to specify the actual donor-source relationship, since this is a fact the transplant team would know with certainty and which directly determines the correct ICD-10-PCS qualifier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('beff45a7-61d7-4efd-bb87-67c9580584ef', 'd2e5a6fe-edd1-421d-b8f7-67d21f9e1037', 1, 'Donor-source relationship should never be queried since it''s considered outside the coder''s scope of interest');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73e0eddc-6136-4524-82e0-254edff07c18', 'd2e5a6fe-edd1-421d-b8f7-67d21f9e1037', 2, 'Assume autologous by default without querying, since it''s a common transplant type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eb1f008-e074-47d1-abba-6362bc4307ee', 'd2e5a6fe-edd1-421d-b8f7-67d21f9e1037', 3, 'Only the blood bank, never the transplant surgical team, may be asked about donor-source relationship');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f97427d-139c-4a37-b43c-2c00ed3e55dd', 'c2ba8f73-e4c5-4fe5-b20b-8ec527380305', 0, 'A non-leading query asking the physician to clarify the actual clinical purpose of the fluid removal (symptomatic relief vs. diagnostic sampling), presented as an open clinical question rather than presuming one specific intent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a2672236-65d0-499f-982b-4f2b99fcaa7c', 'c2ba8f73-e4c5-4fe5-b20b-8ec527380305', 1, 'Diagnostic-versus-therapeutic intent should never be queried, since it''s assumed to always be obvious from context');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('adc76b17-af47-4a3a-9955-150752858ff4', 'c2ba8f73-e4c5-4fe5-b20b-8ec527380305', 2, 'Always default to ''diagnostic'' without querying, regardless of the clinical scenario');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef56daf4-3e7d-442a-8893-153928e7da86', 'c2ba8f73-e4c5-4fe5-b20b-8ec527380305', 3, 'Only the patient, never the treating physician, can clarify procedural intent');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc8ee0e7-9386-41ef-a204-bf3de8a53a8e', '6b7fb775-b644-4272-9fdc-0b8e3b9986b2', 0, 'A query asking the physician to confirm the final, current diagnostic impression/source of the bleed based on all available workup, presented as an open clinical question about the CURRENT determination rather than presuming which finding should govern');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('078d803f-bc3a-4852-9e50-dd6e7ab9cba8', '6b7fb775-b644-4272-9fdc-0b8e3b9986b2', 1, 'No query is ever appropriate once any diagnostic test has been performed, regardless of remaining ambiguity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e3e9f8a-d10d-4d5d-b6b4-105b086ebf42', '6b7fb775-b644-4272-9fdc-0b8e3b9986b2', 2, 'Automatically use the earliest documented impression regardless of subsequent findings');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('006dd685-fc56-4b87-aec9-7d393c25e375', '6b7fb775-b644-4272-9fdc-0b8e3b9986b2', 3, 'The query should presume the later test result is correct and simply ask the physician to sign off');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('312ad1a0-de88-402a-a650-e654a91184f5', '7fb4bb70-f2e0-4fbe-9644-e9a5d622334d', 0, 'EMTALA-related documentation gaps should never be raised via any query or clarification process');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc2757bb-998e-4ca8-a117-d891e57947b8', '7fb4bb70-f2e0-4fbe-9644-e9a5d622334d', 1, 'A non-leading, factually-framed request for documentation clarification/completion (e.g., asking a physician to document the actual time a screening exam was performed, if not already clearly recorded) follows similar non-leading principles to any other query — the goal is accurate, complete documentation of what actually occurred, not suggesting a specific answer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5480ba2e-3994-420f-b2ae-fe17c9c78d61', '7fb4bb70-f2e0-4fbe-9644-e9a5d622334d', 2, 'Only hospital legal counsel, never HIM/coding staff, may ever raise an EMTALA documentation completeness question');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a03e95e-2e43-4221-9007-c48d99ceca25', '7fb4bb70-f2e0-4fbe-9644-e9a5d622334d', 3, 'EMTALA documentation gaps must always be resolved by deleting the incomplete note entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('734043c9-5552-4ee4-9037-3da0504a6e0b', '388eb91d-115d-4b15-9f8b-d214de6892cf', 0, 'A query (or, more commonly, direct documentation feedback/education) to the physician requesting clarification of which basis (time or MDM) was used and ensuring the supporting documentation for that basis is complete, since this determines whether the reported code level is actually supported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('67f25b7b-30a9-4bc3-8797-6d9f33b3f0fb', '388eb91d-115d-4b15-9f8b-d214de6892cf', 1, 'This ambiguity should never be addressed since telehealth E/M coding is assumed to always use MDM by default with no verification needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c2db208-8ac2-49f8-b1ad-f1d52cd381e0', '388eb91d-115d-4b15-9f8b-d214de6892cf', 2, 'Time-basis clarification is never appropriate for telehealth visits specifically, only in-person visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32cb5433-50f5-4f85-ba71-a7877e87e4a5', '388eb91d-115d-4b15-9f8b-d214de6892cf', 3, 'The coder should simply pick whichever basis (time or MDM) supports the higher code level, without seeking clarification');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7d45896-e00e-4d98-b1ec-e9d616cf92b1', '72f833b2-9898-4402-afa8-adad6057cf46', 0, 'A non-leading query presenting the specific RPM finding (e.g., a specific elevated blood pressure reading pattern) and asking the physician whether it represents a clinically significant finding requiring diagnosis/action, or is not clinically significant/likely artifact — genuinely open to either determination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b711dd50-ce3c-499a-82b9-d0157a4fc998', '72f833b2-9898-4402-afa8-adad6057cf46', 1, 'The query should presume the RPM data represents a new diagnosis and ask the physician to simply confirm it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('290dde0c-463a-47a5-89fa-4ac321169f13', '72f833b2-9898-4402-afa8-adad6057cf46', 2, 'RPM data can never be the subject of a query under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('091272b1-7032-4784-a05d-4277727fdadc', '72f833b2-9898-4402-afa8-adad6057cf46', 3, 'Only the RPM device manufacturer, never the treating physician, may be asked to interpret the clinical significance of a reading');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc11a0a3-ee30-40d9-97ef-10c9c20b7f55', 'b4629d55-6d37-47e3-9218-c39657657095', 0, 'Providing a medical screening examination to any individual who comes to the ED requesting examination/treatment, and stabilizing treatment (or an appropriate transfer) for any identified emergency medical condition, regardless of the individual''s ability to pay');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('41b98aad-de8f-46d8-bcfb-b5ad587501b5', 'b4629d55-6d37-47e3-9218-c39657657095', 1, 'Requiring upfront payment or insurance verification before any medical screening examination may be performed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bbe05f25-8531-41c5-b3df-fd0d87b7f064', 'b4629d55-6d37-47e3-9218-c39657657095', 2, 'Applying only to patients who arrive by ambulance, not those who walk in');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb3b2814-757f-46f8-9c5c-4410fdfb7607', 'b4629d55-6d37-47e3-9218-c39657657095', 3, 'Applying only to hospitals in states that have separately opted into EMTALA');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f292cfc2-fd93-4bde-ae47-33318b46e1d8', '2549dd72-838f-4738-b30e-c7c35e2a79c1', 0, 'EMTALA has no documentation or coding relevance whatsoever');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ee577b3-3553-40d7-a2fc-92540d599217', '2549dd72-838f-4738-b30e-c7c35e2a79c1', 1, 'Documentation supporting that a medical screening exam was performed, and (if applicable) an appropriate transfer determination/process was followed, is relevant both to EMTALA compliance demonstration and to accurately coding the ED encounter itself — connecting general documentation-completeness principles already discussed to this specific regulatory context');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91397cb2-ec40-4b07-941a-262687ffa0ca', '2549dd72-838f-4738-b30e-c7c35e2a79c1', 2, 'EMTALA documentation is solely the registration department''s responsibility, with zero coding relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34021a0c-033d-4e04-b8c0-b420caf23344', '2549dd72-838f-4738-b30e-c7c35e2a79c1', 3, 'EMTALA applies only to inpatient admissions, never ED encounters, making it irrelevant to ED coding');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b717936-98cd-4017-b839-dbc7fb0bff99', 'e2d54f10-0475-477c-a8b4-b1a76ba4d9bd', 0, 'Any transfer is automatically EMTALA-compliant regardless of documentation or process followed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b836788c-ee9f-4c7a-a3fd-02f5b0cdf7ad', 'e2d54f10-0475-477c-a8b4-b1a76ba4d9bd', 1, 'An ''appropriate transfer'' under EMTALA generally requires specific conditions to be met (e.g., physician certification that benefits outweigh risks, receiving facility''s agreement to accept the patient, appropriate documentation and equipment/personnel during transport) — an unstabilized transfer not meeting these conditions can constitute an EMTALA violation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07107f8e-ce9b-40f9-8597-f5ecccb43266', 'e2d54f10-0475-477c-a8b4-b1a76ba4d9bd', 2, 'EMTALA transfer requirements apply only to transfers between different states, never within the same state');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52cc5c13-7ce5-4a87-8d35-b0fa35abe937', 'e2d54f10-0475-477c-a8b4-b1a76ba4d9bd', 3, 'Only ambulance-based transfers are ever subject to EMTALA transfer requirements');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4710eaf2-d7a5-4b90-b643-e86162e868c0', '6ea90804-b8d7-468b-94b1-58a977e5f696', 0, 'Accreditation surveys never examine HIM/coding-related practices, focusing exclusively on clinical nursing care');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0502687-5ff3-424f-ad69-d0c62f8a12ff', '6ea90804-b8d7-468b-94b1-58a977e5f696', 1, 'Accreditation surveys typically include review of health record documentation completeness/timeliness, HIM department policies, and related compliance practices as part of assessing an organization''s overall quality/safety and regulatory compliance posture — making HIM/coding practices a real component of survey readiness');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53fb9e67-612b-4b50-95b9-09188d544295', '6ea90804-b8d7-468b-94b1-58a977e5f696', 2, 'Accreditation is entirely voluntary with zero connection to CMS Medicare/Medicaid participation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6999758-83e2-43de-bf6f-2cfe76f8d091', '6ea90804-b8d7-468b-94b1-58a977e5f696', 3, 'Accreditation surveys are conducted only once, at hospital opening, with no ongoing/periodic review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('64aa25ef-27ba-4647-aac1-3871c8a98067', 'fe834a2d-40bf-4ddb-b4f3-a6614728d7ac', 0, 'No ongoing practice is needed; survey readiness can be fully achieved through a short intensive preparation period immediately before a scheduled survey visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a629d8f-c2f1-4728-bace-e905812bdd35', 'fe834a2d-40bf-4ddb-b4f3-a6614728d7ac', 1, 'Maintaining continuous compliance with documentation completeness/timeliness standards, ongoing internal audits, and consistent policy adherence throughout the accreditation cycle (not just before a scheduled survey), since surveys can include unannounced visits and genuine ongoing compliance is more sustainable and lower-risk than periodic ''crisis mode'' preparation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9528ff3d-cdb0-4f6b-a793-839b8b1955e0', 'fe834a2d-40bf-4ddb-b4f3-a6614728d7ac', 2, 'Survey readiness is solely the responsibility of hospital administration, with zero HIM department role');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('584e30b5-3d4b-400a-96ef-5721aa80e345', 'fe834a2d-40bf-4ddb-b4f3-a6614728d7ac', 3, 'Accreditation standards never change, so a one-time compliance achievement is sufficient permanently');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f27d6195-7cc5-41f7-a896-1e50f261eb2e', 'b25f937b-c346-4ff3-bb27-f92d845f2c73', 0, 'Delinquency rates have no relevance to accreditation or regulatory compliance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a92d8d11-2785-472a-b271-8c8bb75a038a', 'b25f937b-c346-4ff3-bb27-f92d845f2c73', 1, 'Excessive record delinquency can be both an accreditation survey finding and a broader documentation-completeness/compliance risk (since incomplete records can affect coding accuracy, continuity of care, and medical-legal defensibility) — tracking and trending supports proactive management rather than discovering the issue only during a survey');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('94dd2bea-9fa1-49fb-bec1-dd037b0c2b0c', 'b25f937b-c346-4ff3-bb27-f92d845f2c73', 2, 'Delinquency tracking is relevant only for billing purposes, with zero accreditation/compliance relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84886f39-2416-4764-8b51-02dcffa1b19e', 'b25f937b-c346-4ff3-bb27-f92d845f2c73', 3, 'Only physicians, never HIM leadership, bear any responsibility for monitoring delinquency rates');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82596a35-ed53-4992-afe0-279de5ad6f48', '2de30ac4-cacd-43f4-b77a-f07bc86b5e52', 0, 'On-call physicians have no EMTALA obligations whatsoever; only ED physicians are covered');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5036183-e048-475e-a741-2e1dfd39e521', '2de30ac4-cacd-43f4-b77a-f07bc86b5e52', 1, 'A hospital must maintain a list of on-call physicians to provide further evaluation/treatment necessary to stabilize a patient with an emergency medical condition, and on-call physicians generally have an obligation to respond within a reasonable time when called — failure to do so can itself raise EMTALA compliance concerns for the hospital');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7b12437e-d4fa-44da-8fd3-72e13b5eeffc', '2de30ac4-cacd-43f4-b77a-f07bc86b5e52', 2, 'On-call obligations apply only to surgical specialties, never medical specialties');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5b07c98-de74-4673-9f28-02d6175346b3', '2de30ac4-cacd-43f4-b77a-f07bc86b5e52', 3, 'On-call physician response time has no bearing on EMTALA compliance');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21370e79-157f-4411-8c6a-da2239114b6f', '1eabd741-012d-45de-b2e6-ac21156c8122', 0, 'No certification is ever required for any transfer under EMTALA');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1142ed49-552a-4afb-9e2f-c5d400fbac87', '1eabd741-012d-45de-b2e6-ac21156c8122', 1, 'A physician (or, in certain circumstances, a qualified medical person with physician consultation) must generally certify that the medical benefits reasonably expected from the transfer outweigh the risks, based on the information available at the time — a required, documented element of an appropriate transfer');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffe119f8-bce1-490b-b749-85888ed7becd', '1eabd741-012d-45de-b2e6-ac21156c8122', 2, 'Certification is required only for transfers occurring at night');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c66b2b8-4d52-442f-9640-2507e9ac93cb', '1eabd741-012d-45de-b2e6-ac21156c8122', 3, 'Certification requirements apply only to pediatric patients');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3c7d97a1-4952-40d2-b65c-d6543e682371', 'c8ab4306-632c-402d-8c9f-b2a60ddef313', 0, 'EMTALA obligations apply only to a hospital''s main, on-campus emergency department, never any off-campus locations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f64edac-b5fd-4196-9936-d5bb3d2b929f', 'c8ab4306-632c-402d-8c9f-b2a60ddef313', 1, 'EMTALA''s medical screening exam and stabilization requirements can extend to qualifying off-campus, hospital-owned locations that meet the regulatory definition of a dedicated emergency department, not solely the main campus ED — a facility should understand which of its locations meet this definition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('30532c39-a3cb-426f-a7e5-83f6cc8046a8', 'c8ab4306-632c-402d-8c9f-b2a60ddef313', 2, 'Off-campus locations are entirely exempt from any federal healthcare regulation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('031331dc-cd36-4240-841d-c5b1a9a9abe0', 'c8ab4306-632c-402d-8c9f-b2a60ddef313', 3, 'Only locations physically attached to the main hospital building are ever subject to EMTALA');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('759efa2c-3f37-46ad-aebf-726f57891f72', '417168ab-cf4e-4e32-8af8-a80cab3d5b68', 0, 'A hospital that has been decertified from Medicare/Medicaid participation entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7d12868-82f5-426d-8171-7fb665ee0522', '417168ab-cf4e-4e32-8af8-a80cab3d5b68', 1, 'A hospital accredited by a CMS-approved accrediting organization (e.g., The Joint Commission) is generally ''deemed'' to meet applicable Medicare Conditions of Participation, streamlining the survey process (though CMS retains authority for certain complaint-driven or validation surveys) rather than requiring a separate, fully duplicative CMS survey');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('146449b2-0746-41f3-8287-d2fc88468184', '417168ab-cf4e-4e32-8af8-a80cab3d5b68', 2, 'Deemed status applies only to physician practices, never hospitals');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80fb818f-d00d-494f-9423-c9021a18f42a', '417168ab-cf4e-4e32-8af8-a80cab3d5b68', 3, 'Deemed status eliminates all federal regulatory oversight of the facility permanently');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6b67844-0009-4ffd-acdd-12de3c0fd8fa', 'f2aa6713-a34f-4955-811d-6e4bae0c36c2', 0, 'No response is needed since accreditation findings are purely advisory with zero consequence');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d50e3e45-fb8f-42d2-8ba0-072ec3a3112b', 'f2aa6713-a34f-4955-811d-6e4bae0c36c2', 1, 'Developing and implementing a corrective action plan addressing the root cause of the finding (consistent with the general corrective-action principles already discussed), since unaddressed accreditation findings can jeopardize deemed status/continued accreditation and, by extension, Medicare/Medicaid participation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23f3dc5a-c743-48b1-b8c4-f9e5d5f5fc13', 'f2aa6713-a34f-4955-811d-6e4bae0c36c2', 2, 'Disputing every survey finding automatically without genuine root-cause investigation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bf25284a-fd7c-4b6c-aa76-fa73ab71802c', 'f2aa6713-a34f-4955-811d-6e4bae0c36c2', 3, 'Accreditation findings only need to be addressed if they also result in a separate CMS citation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15aadd27-413d-432e-b3f9-6c90b7fc5c5e', '48220724-5224-4671-9aba-632e1f6719cd', 0, 'HIM has no role whatsoever in EMTALA compliance; it is purely an ED clinical/operational matter');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('922a05f7-c283-4483-b9de-9b4713142815', '48220724-5224-4671-9aba-632e1f6719cd', 1, 'HIM can contribute by ensuring ED documentation (screening exams, transfer certifications, on-call responses) is complete and properly retained/retrievable, supporting the facility''s ability to demonstrate compliance if reviewed — a records-management/documentation-completeness role complementing the ED''s own clinical compliance responsibilities');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8bedb9b-952b-41ee-a356-f1309eec14b0', '48220724-5224-4671-9aba-632e1f6719cd', 2, 'HIM''s only EMTALA-related role is billing for ED visits, with zero documentation-completeness responsibility');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e2bf85ea-bfbf-42b9-87e6-c2467e4fa5b7', '48220724-5224-4671-9aba-632e1f6719cd', 3, 'EMTALA compliance requires no documentation retention beyond the standard medical record retention period');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('46a19c97-1425-4c52-979a-4bac9bb1b5f1', '0163545c-ed9f-414b-95db-4a857d5ee3de', 0, 'Telehealth can never satisfy any on-call/consultation obligation under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6475f354-0a17-41e0-994f-2ede11d7de24', '0163545c-ed9f-414b-95db-4a857d5ee3de', 1, 'Telehealth-based specialist consultation can be a legitimate way to help satisfy on-call coverage needs in appropriate circumstances, provided the specific arrangement meets applicable regulatory expectations for timely, adequate evaluation supporting stabilization — a practical connection between Domain 5''s telehealth content and Domain 4''s EMTALA on-call discussion');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a01a8f9e-8f42-4b59-b571-1124b7bb27e5', '0163545c-ed9f-414b-95db-4a857d5ee3de', 2, 'Telehealth consultations are entirely unregulated with zero compliance considerations');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('383b8277-d143-406e-903c-a01c50c2110a', '0163545c-ed9f-414b-95db-4a857d5ee3de', 3, 'Only in-person, on-site consultation can ever count toward any EMTALA-related coverage obligation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f8527eef-d7b3-41a2-a042-7f934546a2fa', 'c8b8583e-8924-46b5-af6e-b465d8c4e992', 0, 'Transplant donor-source documentation serves only a single purpose (either clinical/regulatory OR coding), never both, so no integrated review is beneficial');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9bf96bc8-f77c-475f-9ece-f49f77138d26', 'c8b8583e-8924-46b5-af6e-b465d8c4e992', 1, 'Ensuring documentation practices adequately serve BOTH the clinical/regulatory reporting obligations transplant programs carry (e.g., to organ procurement organizations, transplant registries) AND the coding-specificity needs already discussed reduces duplicative documentation effort and the risk that one purpose''s documentation gap goes unnoticed because it appears to satisfy the other purpose');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('644ecdf4-fafe-4232-9b05-dfe60a23def9', 'c8b8583e-8924-46b5-af6e-b465d8c4e992', 2, 'Only the organ procurement organization has any interest in donor-source documentation accuracy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('774f5826-25ab-42cf-9863-94ce3bc54b57', 'c8b8583e-8924-46b5-af6e-b465d8c4e992', 3, 'Coding accuracy and transplant regulatory reporting have no meaningful overlap');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('455ef60c-6476-4ca8-a9d1-11251a77be30', 'b66f0cdc-a96c-4d51-8e3c-642dc8f1d00c', 0, 'Ventilator-hour coding has no meaningful reimbursement impact worth auditing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f3d50d3-5b96-4e86-a4e2-bfdcee10248b', 'b66f0cdc-a96c-4d51-8e3c-642dc8f1d00c', 1, 'Given that ventilator duration directly affects DRG assignment (via the duration-banded procedure codes already discussed) and is dependent on accurate cross-referencing of multiple documentation sources (a recognized documentation-integrity challenge also already discussed), this is a reasonable, targeted area for focused compliance auditing, similar in concept to the POA-accuracy focused-audit rationale discussed earlier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6e752ed6-7978-4d16-a59f-4c635f2386c5', 'b66f0cdc-a96c-4d51-8e3c-642dc8f1d00c', 2, 'Ventilator-hour audits are prohibited since they would require reviewing clinical respiratory therapy documentation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1f7bde13-debd-4826-aa86-b321a38fb334', 'b66f0cdc-a96c-4d51-8e3c-642dc8f1d00c', 3, 'Only the respiratory therapy department, never HIM/coding compliance, has any legitimate interest in ventilator-hour accuracy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('775d584a-7aa0-4e36-8402-2fee8621b057', 'ee8a6cb0-9400-4be3-bdf3-d15dc62b2b9b', 0, 'HIM/coding compliance and quality/patient-safety functions are entirely separate with no productive coordination possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4a59171-f464-4e3f-9c51-eadd48ca9848', 'ee8a6cb0-9400-4be3-bdf3-d15dc62b2b9b', 1, 'Since many of the topics covered in this content (POA/HAC/PSI accuracy, EMTALA documentation, accreditation findings) touch both coding-accuracy AND genuine clinical quality/safety dimensions, coordinating HIM/coding compliance monitoring with the broader quality/safety committee structure supports a more complete, non-siloed understanding of an issue''s full scope and appropriate response');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b984f62f-cc0e-4f08-a26a-0cb01115acaf', 'ee8a6cb0-9400-4be3-bdf3-d15dc62b2b9b', 2, 'Quality/safety committees have no legitimate interest in coding-accuracy-related data');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d5d3cf1-17cc-4811-9039-793bca690a5f', 'ee8a6cb0-9400-4be3-bdf3-d15dc62b2b9b', 3, 'Coordination between these functions is prohibited by HIPAA');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cea59826-d551-440e-aa9d-9e0ab38face0', '4a61988c-14bb-4f8c-bec3-30ecfe7db07a', 0, 'RPM-triggered query patterns have no distinct compliance-monitoring value beyond any other query type');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0499f059-4498-4e0d-837b-7a29701b13ee', '4a61988c-14bb-4f8c-bec3-30ecfe7db07a', 1, 'Similar to the general query-outcome-pattern monitoring principle already established, tracking RPM-specific query outcomes can help identify whether RPM data is being appropriately, individually clinically evaluated versus potentially being used as a basis for pattern-based diagnosis capture without adequate individualized clinical review — relevant given RPM''s growing role and potential HCC/risk-adjustment intersection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f3fb6e70-089c-49e1-ba17-132104c2396b', '4a61988c-14bb-4f8c-bec3-30ecfe7db07a', 2, 'RPM queries should never be tracked or monitored under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a69abefc-af87-454d-a97f-fc2acd65188a', '4a61988c-14bb-4f8c-bec3-30ecfe7db07a', 3, 'Only IT departments, never compliance/CDI programs, have any legitimate interest in RPM query patterns');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e220d76-15df-4c2f-96fe-025d246921d0', 'fd71b8da-2e80-476d-bb01-86a2927cf8f4', 0, 'Telehealth recordings, if created, raise their own distinct retention/access-control considerations (similar in principle to any other form of PHI) that should be addressed through clear policy — an unaddressed gap here could create both a compliance and a records-management risk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82c7234f-08ae-471e-9e57-d0873c82d5ad', 'fd71b8da-2e80-476d-bb01-86a2927cf8f4', 1, 'Telehealth recordings require no specific policy consideration since they are treated identically to a text-based visit note automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ee3b7fa-aaf4-470b-9267-e833b77092f3', 'fd71b8da-2e80-476d-bb01-86a2927cf8f4', 2, 'Telehealth recordings should never be created under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('95e0d3a0-f28e-45a5-8817-177699677af0', 'fd71b8da-2e80-476d-bb01-86a2927cf8f4', 3, 'Only the telehealth platform vendor bears any responsibility for recording retention/access, with zero facility-side policy needed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1dc2bff1-e624-4211-b2d3-6f8aa6f0c9e0', 'ed47ee09-7c98-4f69-a0b1-bbf1ec51f927', 0, 'Information-blocking exception practices, once established, never need reassessment regardless of how the underlying data landscape changes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0efed4c6-66d2-44c2-84c3-f1ae9e315c79', 'ed47ee09-7c98-4f69-a0b1-bbf1ec51f927', 1, 'As newer data types (RPM data, telehealth records) become a larger part of a patient''s overall health information, a facility''s information-blocking exception practices and patient-access processes should be periodically reassessed to ensure they appropriately, consistently apply to these newer data types as well — not just the data types/formats that existed when the original policy was written');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9d204ec-b887-4989-87a1-55c3c34eb5d0', 'ed47ee09-7c98-4f69-a0b1-bbf1ec51f927', 2, 'RPM and telehealth data are categorically exempt from information-blocking requirements entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aef76651-17b8-4549-9ade-37d03ef5fff3', 'ed47ee09-7c98-4f69-a0b1-bbf1ec51f927', 3, 'Only clinical notes, never any device-generated or telehealth-generated data, are ever subject to information-blocking rules');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('afd39bf4-76f6-4d45-af68-5646c672bba3', '560ecb51-faea-4dbf-b12a-0c84a9c1e0c6', 0, 'EMTALA has never been amended or interpreted differently since its original enactment, making periodic policy review unnecessary');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f89135ec-6c21-45ec-a1cc-c251415d54fe', '560ecb51-faea-4dbf-b12a-0c84a9c1e0c6', 1, 'Regulatory interpretation, CMS guidance, and a facility''s own operational circumstances (new off-campus locations, expanded telehealth-based on-call arrangements, etc.) can evolve over time, meaning a static, never-updated EMTALA policy risks becoming inconsistent with current requirements or the facility''s actual current operations — consistent with the broader ''ongoing monitoring, not one-time achievement'' compliance theme already established for other regulatory areas');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe4d620d-d3b4-45e5-8269-d488511a421b', '560ecb51-faea-4dbf-b12a-0c84a9c1e0c6', 2, 'EMTALA policy review is solely the responsibility of external legal counsel, with zero facility-side periodic review role');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f71f1bab-7fab-4c6a-86a0-eac79b40c25d', '560ecb51-faea-4dbf-b12a-0c84a9c1e0c6', 3, 'Only newly-opened hospitals need an EMTALA policy; established hospitals are permanently exempt from any further review');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f530ddd0-67d3-4a6f-b4aa-1846381901d4', '4de07d6f-1b7c-402a-a600-45abce445cad', 0, 'RPM device data should always be assumed 100% accurate with no verification, since it comes directly from a device rather than manual entry');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b41a440-e2a9-4a49-b40b-eef81bead917', '4de07d6f-1b7c-402a-a600-45abce445cad', 1, 'RPM data, while valuable, can be subject to device calibration issues, transmission errors, or patient-usage errors — clinical documentation incorporating RPM data for diagnosis/coding purposes ideally reflects a clinician''s review/interpretation of that data (similar to the earlier principle about raw test results generally requiring clinical interpretation) rather than treating raw device readings as automatically equivalent to a clinical determination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('40915322-cfba-42f6-92a4-4ec9ea79bd24', '4de07d6f-1b7c-402a-a600-45abce445cad', 2, 'RPM data can never be used to support any clinical documentation or coding under any circumstance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83f009a4-d693-4d02-b9a0-f4d116d0619a', '4de07d6f-1b7c-402a-a600-45abce445cad', 3, 'RPM data is relevant only to device manufacturers, never to HIM/coding data-integrity considerations');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36d7c4c2-19e2-4ec4-b8b8-ef8a6a99e83b', '9ca273a4-3285-4190-adc9-b917fc2904f2', 0, 'Telehealth platforms require no different security/privacy consideration than any other communication tool, regardless of the sensitivity of information discussed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f323f13-15b7-4d0a-b2b8-fa6aff7b1e9b', '9ca273a4-3285-4190-adc9-b917fc2904f2', 1, 'A telehealth platform used for Part 2-covered substance use disorder treatment should meet appropriate security/privacy safeguards (encryption, access controls) consistent with both general HIPAA Security Rule expectations and the heightened sensitivity of Part 2-covered information — a platform-selection/configuration consideration connecting Domain 4''s Part 2 discussion to Domain 5''s technology-safeguard concepts');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('da52ac7e-5457-4d89-98ca-4d8712b30381', '9ca273a4-3285-4190-adc9-b917fc2904f2', 2, '42 CFR Part 2 has no bearing on telehealth platform selection or configuration in any way');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bba9d35a-d826-43ef-b43e-85bb40a952b6', '9ca273a4-3285-4190-adc9-b917fc2904f2', 3, 'Any consumer video-calling application, with no specific security features, is automatically sufficient for Part 2-covered telehealth encounters');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e540ff1b-80f3-4731-ac39-6a455fb6c036', 'b34a7b8a-5573-4562-a57c-6244530a780a', 0, 'Telehealth documentation is held to a categorically lower completeness standard by design, with no need to apply the same documentation-sufficiency review already established for in-person visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b535e6f4-d096-4507-ac89-3229af59ce09', 'b34a7b8a-5573-4562-a57c-6244530a780a', 1, 'The same documentation-sufficiency principles discussed throughout this content (supporting diagnosis/coding decisions, resolving ambiguity, querying when needed) apply regardless of visit modality — a telehealth visit''s documentation should still support whatever diagnoses/codes are being reported for that encounter, just as thoroughly as an in-person visit would need to');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7aa1012-b632-40ea-81c5-0d865376a905', 'b34a7b8a-5573-4562-a57c-6244530a780a', 2, 'Telehealth visits can never generate a codeable E/M or other billable service, regardless of documentation quality');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('931624b6-3d68-43d7-9b82-4d0c0a91e9f0', 'b34a7b8a-5573-4562-a57c-6244530a780a', 3, 'Only video-based telehealth, never audio-only telehealth, requires any documentation-sufficiency consideration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b836663-2b03-404a-92d6-c066c83e4b04', 'ca565a47-ce7a-42c0-9cbe-52752d4dc47b', 0, 'Whether the platform integrates with the organization''s EHR in a way that allows the telehealth encounter''s documentation to be captured, reviewed, and coded consistently with the organization''s standard documentation/coding workflows — rather than existing as a disconnected, siloed system requiring manual reconciliation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b856e45-1735-43df-b3fd-91c83a08cfa8', 'ca565a47-ce7a-42c0-9cbe-52752d4dc47b', 1, 'Only the platform''s video/audio quality matters; documentation/EHR integration is irrelevant to coding workflow evaluation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('800fe176-6291-402c-9854-f1cc837b0818', 'ca565a47-ce7a-42c0-9cbe-52752d4dc47b', 2, 'Telehealth platforms never need any EHR integration since telehealth visits are not coded the same way as in-person visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('32f8adcb-bc7b-4b26-a300-894cafa4c528', 'ca565a47-ce7a-42c0-9cbe-52752d4dc47b', 3, 'Cost is the only relevant factor in telehealth platform evaluation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3817bfb1-1898-4ba0-ab1e-82b7a9b379f5', '8e4904ec-bd5f-4c5e-a09e-875ee6985909', 0, 'RPM data should be configured to automatically generate diagnosis codes without any clinician review step, to maximize efficiency');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a43beb7b-33b8-473d-84cc-0038b9af7ed8', '8e4904ec-bd5f-4c5e-a09e-875ee6985909', 1, 'RPM data integration should ideally route abnormal/significant readings to a clinician''s review queue (rather than silently populating the chart with no review prompt), supporting the principle that RPM data should be clinically reviewed/interpreted before being relied upon for diagnosis or coding purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ffd8423-5a3b-4619-9a43-549f7d5e59d9', '8e4904ec-bd5f-4c5e-a09e-875ee6985909', 2, 'RPM data integration has no bearing on whether clinical review occurs; that is a purely separate workflow question');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('481af1e2-5363-45ac-83bf-4e882f4500ba', '8e4904ec-bd5f-4c5e-a09e-875ee6985909', 3, 'RPM data should never be integrated into the EHR at all, remaining in a completely separate system');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e558cee-67de-43e4-803b-0e375c45e732', '9ed33764-84d4-4688-83db-46ba76d3eaf3', 0, 'Only the platform''s data-transmission speed matters; data-quality/validation features are irrelevant to evaluation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2be36bb9-a719-422b-8ed6-f682a17b6346', '9ed33764-84d4-4688-83db-46ba76d3eaf3', 1, 'Evaluating whether the platform includes data-validation features (e.g., flagging implausible readings, tracking device calibration status, distinguishing patient-entered from device-transmitted data) supports the broader data-integrity goals already discussed for RPM data specifically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c1560ef-4557-4602-b74f-a3c2c67c8ae6', '9ed33764-84d4-4688-83db-46ba76d3eaf3', 2, 'RPM platforms are all functionally identical in data-quality terms, making vendor evaluation on this dimension unnecessary');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('823c9216-1ac9-4188-b21b-16d9f491da47', '9ed33764-84d4-4688-83db-46ba76d3eaf3', 3, 'Data-validation features are solely the treating clinician''s responsibility, with zero relevance to platform selection');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7392fbc3-ffff-473c-8144-b4696801d3ae', 'fb6c8cea-a8a4-4805-86e5-93e305f8681e', 0, 'Telehealth platforms used for this purpose should reasonably support reliable, timely connectivity and appropriate documentation capture of the consultation (supporting both patient care and the compliance-documentation needs already discussed), given the stakes involved in EMTALA-related stabilization decisions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a3ea89c-8dfd-42fd-9cde-815ee9f09c4c', 'fb6c8cea-a8a4-4805-86e5-93e305f8681e', 1, 'Platform reliability is irrelevant for EMTALA-related telehealth consultations specifically, though it might matter for routine telehealth visits');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5653787-920b-4c01-962d-55fc4b35a1eb', 'fb6c8cea-a8a4-4805-86e5-93e305f8681e', 2, 'EMTALA-related telehealth consultations require no different technology consideration than a routine, non-urgent telehealth follow-up visit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('105d4337-6433-411f-b21d-d99493675bf8', 'fb6c8cea-a8a4-4805-86e5-93e305f8681e', 3, 'Only audio-only telehealth may ever be used for EMTALA-related specialist consultations, never video');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45dfdc0b-8487-4f3a-a012-035d7072f4ab', '5e51c0cc-3f80-4065-839b-5facc977b679', 0, 'Delinquency/completeness metrics should be tracked manually via spreadsheet only, with the EHR system providing no relevant reporting capability');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a964e7d-f0aa-45a5-974e-9278adbe2cf3', '5e51c0cc-3f80-4065-839b-5facc977b679', 1, 'Leveraging EHR/HIM system reporting capabilities to generate ongoing, real-time (or near-real-time) documentation completeness/delinquency metrics supports the continuous survey-readiness practice already discussed, rather than relying on periodic manual audits alone');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ed88ead-35bb-4517-987a-f347a9c3a884', '5e51c0cc-3f80-4065-839b-5facc977b679', 2, 'EHR systems have no capability to report on documentation completeness metrics of any kind');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f45159a5-8778-4dd4-8b45-9b1429f646ac', '5e51c0cc-3f80-4065-839b-5facc977b679', 3, 'Documentation completeness metrics are relevant only during the specific week of a scheduled survey, requiring no ongoing system-based tracking');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('129f150d-db6f-40b3-8a92-bed3379b5150', 'c2de3ddf-73da-4336-9fea-e999b1ee353e', 0, 'Each of these represents an entirely separate, unrelated skill set with no unifying theme, best learned and applied in complete isolation from one another');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a95c2fa-2576-40e5-9616-70f0ebc561bf', 'c2de3ddf-73da-4336-9fea-e999b1ee353e', 1, 'These collectively reflect a broadening scope of HIM/coding technology literacy — from using coding-support tools, to understanding how data moves and is protected, to now understanding how NEWER data sources (device-generated, telehealth-generated) fit into the same underlying documentation-integrity and coding-accuracy principles that have always applied to more traditional documentation sources');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bcc58c5b-2398-4762-b6a3-9b0d07878c16', 'c2de3ddf-73da-4336-9fea-e999b1ee353e', 2, 'Only the encoder/CAC topic remains relevant to CCS-credentialed coders going forward; the other topics are purely IT-department concerns with declining relevance');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9908bd8c-dd47-49e1-9b2d-845a02bb9509', 'c2de3ddf-73da-4336-9fea-e999b1ee353e', 3, 'This trajectory suggests HIM/coding professionals should stop developing clinical/coding knowledge entirely and focus exclusively on IT skills');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('596ff63f-a22a-4586-a579-122d8e9bb20d', '574f900f-fac7-4d94-928a-02e3d1a31d64', 0, 'The five domains are administratively convenient categories with zero practical interconnection in real coding work');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fbe6c2b-dbe0-47ae-bf35-88fcd91a6415', '574f900f-fac7-4d94-928a-02e3d1a31d64', 1, 'Real-world coding scenarios frequently span multiple domains simultaneously (as illustrated throughout this paper — e.g., HCC coding touching Domain 1 specificity, Domain 2 documentation verification, Domain 3 query practice, and Domain 4 compliance/audit exposure all at once), making integrated, cross-domain judgment a genuine, practical CCS competency rather than five isolated skill silos');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a16d350-8b69-4246-afc6-867250f424fb', '574f900f-fac7-4d94-928a-02e3d1a31d64', 2, 'Only Domain 1 (coding knowledge) matters in practice; the other four domains are purely theoretical exam content with no real-world application');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cae078f4-3ab7-4798-8136-3f21ad0664fc', '574f900f-fac7-4d94-928a-02e3d1a31d64', 3, 'Cross-domain integration is relevant only to CDI specialists, never to coders performing primary code assignment');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
